  const choices=type=>Array.from({length:12},(_,index)=>`<button class="pet-test-choice" type="button" data-pet-choice="${type}" data-pet-number="${index+1}">ตัวที่ ${index+1}</button>`).join("");cats.innerHTML=choices("cat");
