      const sent=Number(slot.sent?.[reqId])||0,remain=Math.max(0,req.qty-sent),have=v15ReqHave(s,req),qty=Math.min(remain,have);
      if(qty<=0)throw new Error("ของในกระเป๋าไม่พอ");
