      s.clientSaveRevision=(Number(s.clientSaveRevision)||0)+1;s.clientLocalEditAt=Date.now();nextState=cloneData(s);
      tx.set(dayRef,{...cloneData(day),updatedAt:fs.serverTimestamp()},{merge:false});
