    if($("gardenNavBtn"))$("gardenNavBtn").onclick=()=>{closeModal();if(visitContext){draw();showWeatherToast(`🏡 กำลังอยู่สวน ${visitContext.name}`)}else returnToFarm()};
    if($("inventoryNavBtn"))$("inventoryNavBtn").onclick=()=>inventory();
    if($("shopNavBtn"))$("shopNavBtn").onclick=()=>showShop("home");
