        try{const {db,fs}=await getFirebaseContext(),gRef=fs.doc(db,"gardens",visitContext.memberKey),sRef=fs.doc(db,"saves",currentMemberKey);let ownNext,plots;await fs.runTransaction(db,async tx=>{const [g,o]=await Promise.all([tx.get(gRef),tx.get(sRef)]);plots=(g.data().plots||[]).map(normalizePlot);const q=plots[index];ensurePlotPhase(q);if(!q?.takeover||q.takeover.by!==currentMemberKey||Number(q.takeover.until)<=NOW()||q.phase!=="ready")throw new Error("แปลงนี้ไม่พร้อมเก็บ");const own=normalizeState(o.data(),currentMember);own.bag[crop]=(Number(own.bag[crop])||0)+qty;plots[index]={...emptyPlot(),takeover:q.takeover};ownNext=own;tx.set(gRef,{plots:cloneData(plots),updatedAt:fs.serverTimestamp()},{merge:true});tx.set(sRef,{...cloneData(own),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false})});Y26_applyOwnState(ownNext);state.plots=plots.map(normalizePlot);draw();showWeatherToast(`🌾 เก็บ ${CROPS[crop].name} ×${qty} เข้ากระเป๋าคุณแล้ว`)}catch(e){message("เก็บไม่ได้",e.message||"กรุณาลองใหม่")}return true
