  /* Expired Take Over crops disappear. */
  let lastTakeCleanup=0;async function cleanupTakeovers(){if(!cloudReady||NOW()-lastTakeCleanup<30000)return;const src=state;if(!src?.plots?.some(p=>p?.takeover&&Number(p.takeover.until)<=NOW()))return;lastTakeCleanup=NOW();const key=visitContext?.memberKey||currentMemberKey;if(!key)return;try{const {db,fs}=await getFirebaseContext(),gRef=fs.doc(db,"gardens",key);let plots;await fs.runTransaction(db,async tx=>{const g=await tx.get(gRef);if(!g.exists())return;plots=(g.data().plots||[]).map(normalizePlot);let changed=false;plots=plots.map(p=>{if(p?.takeover&&Number(p.takeover.until)<=NOW()){changed=true;return emptyPlot()}return p});if(changed)tx.set(gRef,{plots:cloneData(plots),updatedAt:fs.serverTimestamp()},{merge:true})});if(plots&&visitContext){state.plots=plots;draw()}else if(plots&&!visitContext){/* R34.12.4: gardens is public mirror only; never roll owner plots backward */ try{globalThis.YN_R341204?.publishOwnerNow?.(true)}catch(_){}}}catch(e){console.warn("takeover cleanup",e)}}

  /* ---------- standard plot overlay sizing + labels ---------- */
  const _drawOverlay=draw;draw=function(){const r=_drawOverlay();document.querySelectorAll("#plots .status-badge,#plots .angel-status-badge").forEach(x=>x.classList.add("ynu-plot-overlay"));state?.plots?.forEach((p,i)=>{const b=document.querySelector(`#plots [data-plot-index="${i}"]`)||document.querySelectorAll("#plots .plot")[i];if(!b)return;if(takeoverActive(p)){b.classList.add("ynu-takeover-plot");let icon=b.querySelector(".ynu-deed-overlay");if(!icon){icon=document.createElement("img");icon.className="status-badge ynu-plot-overlay ynu-deed-overlay";icon.src=DEED_ITEM.image;icon.alt="โฉนด Take Over";b.appendChild(icon)}let e=b.querySelector(".ynu-takeover-label");if(!e){e=document.createElement("span");e.className="ynu-takeover-label";b.appendChild(e)}e.textContent=`${p.takeover.byName} ได้เทคโอเวอร์แปลงนี้ • ${fmt(p.takeover.until-NOW())}`}});cleanupTakeovers();return r};

  /* ---------- own worm spray: 5 small / 12 giant ---------- */
  async function sprayOwnWorm(index){const p=(ownState||state)?.plots?.[index];if(!p?.crop||p.phase!=="worm")return;const giant=typeof wormTypeOf==="function"&&wormTypeOf(p)==="giant",cost=giant?12:5;try{await settlePendingCloudSave();const {db,fs}=await getFirebaseContext(),sRef=fs.doc(db,"saves",currentMemberKey),gRef=fs.doc(db,"gardens",currentMemberKey);let next;await fs.runTransaction(db,async tx=>{const [sSnap,gSnap]=await Promise.all([tx.get(sRef),tx.get(gRef)]);const s=normalizeState(sSnap.data(),currentMember);if(Number(s.specials?.wormKillerSpray||0)<cost)throw new Error(`สเปรย์แก้หนอนไม่พอ ต้องใช้ ${cost} ขวด`);const plots=s.plots.map(normalizePlot),q=plots[index];if(q.phase!=="worm")throw new Error("หนอนหายไปแล้ว");s.specials.wormKillerSpray-=cost;const c=CROPS[q.crop];q.phase="growing2";q.worm=false;delete q.wormType;q.phaseEndsAt=NOW()+Math.max(MIN,c.totalMs-c.waterMs);s.plots=plots;incrementMissionOn(s,"clearWorms",1);next=s;tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(gRef,{plots:cloneData(plots),updatedAt:fs.serverTimestamp()},{merge:true})});Y26_applyOwnState(next);state=ownState;draw();showWeatherToast(`🪱 กำจัดหนอนแล้ว • ใช้สเปรย์ ${cost} ขวด`)}catch(e){message("กำจัดไม่ได้",e.message||"กรุณาลองใหม่")}}
  const _tapWorm=tapPlot;tapPlot=async function(index){if(!visitContext){const p=(ownState||state)?.plots?.[index];if(p){ensurePlotPhase(p);if(p.phase==="worm"&&Number((ownState||state)?.specials?.wormKillerSpray||0)>0){const giant=typeof wormTypeOf==="function"&&wormTypeOf(p)==="giant",cost=giant?12:5;$("modalContent").innerHTML=`<section class="feature-panel ynu-confirm"><h2>🪱 ${giant?"ไจแอนท์หนอน":"หนอนเล็ก"}</h2><p>ใช้สเปรย์แก้หนอน ${cost} ขวด เพื่อกำจัดทันทีไหม?</p><div><button id="ynuSprayWorm">ใช้สเปรย์</button><button id="ynuOldWorm">วิธีเดิม</button></div></section>`;$("ynuSprayWorm").onclick=()=>{closeModal();sprayOwnWorm(index)};$("ynuOldWorm").onclick=()=>{closeModal();_tapWorm(index)};openModal();return}}}return _tapWorm(index)};

  /* ---------- coconut frog/fish total 4 per rolling hour ---------- */
  const _catchCoco=catchCoconutRiverCreature;catchCoconutRiverCreature=async function(index){const s=ownState||state;if(!s)return;const now=NOW(),h=s.coconutCatchHourly||{};if(!h.windowStart||now-Number(h.windowStart)>=HOUR){h.windowStart=now;h.count=0}s.coconutCatchHourly=h;if(Number(h.count||0)>=4)return message("พักก่อนน๊า","ชั่วโมงนี้เก็บกบ/ปลาครบ 4 ครั้งแล้วค่ะ");const before=(Number(s.coconutRiverItems?.frog1)||0)+(Number(s.coconutRiverItems?.frog2)||0)+(Number(s.coconutRiverItems?.frog3)||0)+(Number(s.coconutRiverItems?.frog4)||0)+(Number(s.coconutRiverItems?.fish1)||0)+(Number(s.coconutRiverItems?.fish2)||0)+(Number(s.coconutRiverItems?.fish3)||0)+(Number(s.coconutRiverItems?.fish4)||0);await _catchCoco(index);const nowS=ownState||state,after=(Number(nowS.coconutRiverItems?.frog1)||0)+(Number(nowS.coconutRiverItems?.frog2)||0)+(Number(nowS.coconutRiverItems?.frog3)||0)+(Number(nowS.coconutRiverItems?.frog4)||0)+(Number(nowS.coconutRiverItems?.fish1)||0)+(Number(nowS.coconutRiverItems?.fish2)||0)+(Number(nowS.coconutRiverItems?.fish3)||0)+(Number(nowS.coconutRiverItems?.fish4)||0);if(after>before){nowS.coconutCatchHourly=nowS.coconutCatchHourly||{windowStart:now,count:0};if(!nowS.coconutCatchHourly.windowStart||now-nowS.coconutCatchHourly.windowStart>=HOUR)nowS.coconutCatchHourly={windowStart:now,count:0};nowS.coconutCatchHourly.count=(Number(nowS.coconutCatchHourly.count)||0)+1;save()}};

  /* ---------- manage current farm (fast, optional; old per-plot remains) ---------- */
  function pageRange(){const p=Math.max(1,Math.min(4,(typeof farmPlotPage==="number"?farmPlotPage:0)+1));return[(p-1)*12,p*12]}
  function showGardenManager(){if(visitContext)return message("จัดการทั้งสวน","ใช้ได้เฉพาะสวนของตัวเองค่ะ");const [a,b]=pageRange();$("modalContent").innerHTML=`<section class="feature-panel ynu-garden-manager"><h2>🌱 จัดการทั้งสวน</h2><p class="feature-subtitle">จัดการเฉพาะแปลง ${a+1}–${b} • การกดทีละแปลงแบบเดิมยังใช้ได้</p><div class="ynu-manager-grid"><button data-ynu-manager="plant">🌱 ปลูกทั้งหมด</button><button data-ynu-manager="boost">🍰 เร่งโตทั้งหมด</button><button data-ynu-manager="angel">🪽 ปีกนางฟ้าทั้งหมด</button><button data-ynu-manager="worms">🪱 จัดการหนอนทั้งหมด</button></div></section>`;document.querySelectorAll("[data-ynu-manager]").forEach(b=>b.onclick=()=>({plant:showBulkSeed,boost:showBulkBoost,angel:bulkAngel,worms:bulkWorms}[b.dataset.ynuManager])());openModal()}
  function showBulkSeed(){const [a,b]=pageRange(),empty=(ownState||state).plots.slice(a,b).filter(p=>!p?.crop&&!(p?.takeover&&Number(p.takeover.until)>NOW()&&p.takeover.by!==currentMemberKey)).length;if(!empty)return message("ปลูกทั้งหมด","ไม่มีแปลงว่างในฟาร์มหน้านี้");$("modalContent").innerHTML=`<section class="feature-panel"><h2>🌱 ปลูกทั้งหมด ${empty} แปลง</h2><div class="ynu-seed-grid">${Object.entries(CROPS).map(([k,c])=>`<button data-bulk-seed="${k}"><img src="${c.selectImg}" alt="${esc(c.name)}"><span>${esc(c.name)}</span></button>`).join("")}</div></section>`;document.querySelectorAll("[data-bulk-seed]").forEach(x=>x.onclick=()=>bulkPlant(x.dataset.bulkSeed));openModal()}
  async function bulkPlant(key){
    const [a,b]=pageRange(),c=CROPS[key],s=ownState||state;if(!c||!s)return;const now=NOW(),targets=[];
    for(let i=a;i<b;i++){const p=s.plots[i];if(!p?.crop&&!(p?.takeover&&Number(p.takeover.until)>now&&p.takeover.by!==currentMemberKey))targets.push(i)}
    if(!targets.length)return message("ปลูกไม่ได้","ไม่มีแปลงว่างในฟาร์มหน้านี้");const costEach=Number(c.seedCostMerit)||0,totalCost=costEach*targets.length;
    if(totalCost&&(Number(s.merit)||0)<totalCost)return message("ปลูกไม่ได้",`ต้องใช้ ${totalCost} กุศล สำหรับ ${targets.length} แปลง • มี ${Number(s.merit)||0}`);
    targets.forEach(i=>{s.angelPlantCounter=(Number(s.angelPlantCounter)||0)+1;const angel=s.angelPlantCounter>=30;if(angel)s.angelPlantCounter=0;s.plots[i]=normalizePlot({crop:key,phase:"growing1",phaseEndsAt:now+c.waterMs,plantedAt:now,wateredAt:0,worm:false,angel})});
    if(totalCost)s.merit-=totalCost;incrementMissionOn(s,"dailyPlantCrops",targets.length);ownState=s;state=s;saveLocalOnly(s);save();closeModal();draw();updateMeritUI();showWeatherToast(`🌱 ปลูก ${c.name} พร้อมกัน ${targets.length} แปลงแล้ว`);
  }
  function showBulkBoost(){const s=ownState||state,items=[...Object.entries(CAKE_ITEMS||{}),...Object.entries(COCONUT_ITEMS||{})].filter(([k])=>Number(s.specials?.[k]||0)>0);if(!items.length)return message("เร่งโตทั้งหมด","ไม่มีเค้กหรือมะพร้าวเร่งโตในกระเป๋า");$("modalContent").innerHTML=`<section class="feature-panel"><h2>🍰 เลือกไอเท็มเร่งโต</h2><div class="ynu-seed-grid">${items.map(([k,i])=>`<button data-bulk-boost="${k}"><img src="${i.image}" alt="${esc(i.name)}"><span>${esc(i.name)} • มี ×${s.specials[k]}</span></button>`).join("")}</div></section>`;document.querySelectorAll("[data-bulk-boost]").forEach(x=>x.onclick=()=>bulkBoost(x.dataset.bulkBoost));openModal()}
  async function bulkBoost(key){
    const [a,b]=pageRange(),s=ownState||state,item=(SPECIAL_ITEMS||{})[key]||(CAKE_ITEMS||{})[key]||(COCONUT_ITEMS||{})[key];if(!s||!item||!Number(item.boost))return message("ใช้ไม่ได้","ไม่พบข้อมูลไอเท็มเร่งโต");
    const now=NOW(),boost=Math.max(0,Math.min(100,Number(item.boost)||0)),targets=[];for(let i=a;i<b;i++){const p=s.plots[i];if(!p?.crop)continue;ensurePlotPhaseStandalone(p);if(p.phase==="ready"||p.phase==="worm")continue;if(p?.takeover&&Number(p.takeover.until)>now&&p.takeover.by!==currentMemberKey)continue;if(["growing1","needsWater","growing2"].includes(p.phase))targets.push(i)}
    if(!targets.length)return message("ใช้ไม่ได้","ไม่มีแปลงที่เร่งโตได้");if(Number(s.specials?.[key]||0)<targets.length)return message("ใช้ไม่ได้",`ไอเท็มไม่พอ ต้องใช้ ${targets.length} ชิ้น • มี ${Number(s.specials?.[key]||0)}`);
    for(const i of targets){const p=s.plots[i],crop=CROPS[p.crop];ensurePlotPhaseStandalone(p);if(boost>=100){p.phase="ready";p.phaseEndsAt=0;p.wateredAt=Number(p.wateredAt)||now;p.worm=false;delete p.wormType}else{let rem;if(p.phase==="growing1")rem=Math.max(0,Number(p.phaseEndsAt||0)-now)+Math.max(MIN,Number(crop.totalMs||0)-Number(crop.waterMs||0));else if(p.phase==="needsWater")rem=Math.max(MIN,Number(crop.totalMs||0)-Number(crop.waterMs||0));else rem=Math.max(0,Number(p.phaseEndsAt||0)-now);const nr=Math.max(0,Math.round(rem*(1-boost/100)));p.wateredAt=Number(p.wateredAt)||now;p.worm=false;delete p.wormType;if(nr<=1000){p.phase="ready";p.phaseEndsAt=0}else{p.phase="growing2";p.phaseEndsAt=now+Math.max(1000,nr)}}s.plots[i]=normalizePlot(p)}
    s.specials[key]-=targets.length;ownState=s;state=s;saveLocalOnly(s);save();closeModal();draw();showWeatherToast(`⚡ เร่งโต ${targets.length} แปลงเรียบร้อย`);
  }
  async function bulkAngel(){
    const [a,b]=pageRange(),s=ownState||state;if(!s)return;const now=NOW(),targets=[];for(let i=a;i<b;i++){const p=s.plots[i];if(!p?.crop)continue;ensurePlotPhaseStandalone(p);if(p.angel)continue;if(p?.takeover&&Number(p.takeover.until)>now&&p.takeover.by!==currentMemberKey)continue;targets.push(i)}
    if(!targets.length)return message("ใช้ไม่ได้","ไม่มีแปลงที่ต้องใช้ปีกนางฟ้า");if(Number(s.specials?.[ANGEL_KEY]||0)<targets.length)return message("ใช้ไม่ได้",`แคปซูลไม่พอ ต้องใช้ ${targets.length} • มี ${Number(s.specials?.[ANGEL_KEY]||0)}`);
    targets.forEach(i=>{s.plots[i].angel=true;s.plots[i]=normalizePlot(s.plots[i])});s.specials[ANGEL_KEY]-=targets.length;ownState=s;state=s;saveLocalOnly(s);save();closeModal();draw();showWeatherToast(`🪽 ใช้ปีกนางฟ้า ${targets.length} แปลงแล้ว`);
  }
  async function bulkWorms(){
    const [a,b]=pageRange();
    try{
      await settlePendingCloudSave();
      const {db,fs}=await getFirebaseContext(),sRef=fs.doc(db,"saves",currentMemberKey),gRef=fs.doc(db,"gardens",currentMemberKey);
      let next,cleared=0,totalCost=0;
      await fs.runTransaction(db,async tx=>{
        const [ss,gg]=await Promise.all([tx.get(sRef),tx.get(gRef)]);
        if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");
        const s=normalizeState(ss.data(),currentMember),plots=(gg.exists()&&Array.isArray(gg.data()?.plots)?gg.data().plots:s.plots).map(normalizePlot);
        while(plots.length<PLOT_COUNT)plots.push(emptyPlot());
        const now=NOW(),targets=[];
        for(let i=a;i<b;i++){
          const p=plots[i];if(!p?.crop)continue;ensurePlotPhaseStandalone(p);
          if(p.phase!=="worm")continue;if(p?.takeover&&Number(p.takeover.until)>now&&p.takeover.by!==currentMemberKey)continue;
          const giant=typeof wormTypeOf==="function"&&wormTypeOf(p)==="giant";targets.push({i,cost:giant?12:5});
        }
        if(!targets.length)throw new Error("ไม่พบหนอนในฟาร์มหน้านี้");
        totalCost=targets.reduce((n,x)=>n+x.cost,0);
        if(Number(s.specials?.wormKillerSpray||0)<totalCost)throw new Error(`สเปรย์ไม่พอ ต้องใช้ ${totalCost} ขวด • มี ${Number(s.specials?.wormKillerSpray||0)}`);
        for(const {i} of targets){const p=plots[i],c=CROPS[p.crop];p.phase="growing2";p.worm=false;delete p.wormType;p.wateredAt=Number(p.wateredAt)||now;p.phaseEndsAt=now+Math.max(MIN,Number(c.totalMs||0)-Number(c.waterMs||0));cleared++}
        s.specials.wormKillerSpray-=totalCost;incrementMissionOn(s,"clearWorms",cleared);s.plots=plots;
        if(currentMember==="Aida"&&adminProfile?.role==="admin"&&typeof ensureAdminStock==="function")ensureAdminStock(s);
        next=s;
        tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
        tx.set(gRef,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),plots:cloneData(plots),updatedAt:fs.serverTimestamp()},{merge:true});
      });
      Y26_applyOwnState(next);lastGardenHash=plotHash(next.plots);state=ownState;closeModal();draw();showWeatherToast(`🪱 กำจัดหนอน ${cleared} ตัวแล้ว • ใช้สเปรย์ ${totalCost} ขวด`);
    }catch(e){message("กำจัดไม่ได้",e.message||"กรุณาลองใหม่")}
  }
  function mountManagerButton(){if($("ynuGardenManagerBtn"))return;const b=document.createElement("button");b.id="ynuGardenManagerBtn";b.className="ynu-garden-manager-button";b.type="button";b.innerHTML="🌱<b>จัดการทั้งสวน</b>";b.onclick=showGardenManager;$("gameScreen")?.appendChild(b)}setTimeout(mountManagerButton,0);

  /* ---------- Dog hotel bath / massage ---------- */
  function careMeta(type){return type==="bath"?{title:"อาบน้ำสัตว์",image:"dog-bath-status.png?v=1",done:"อาบน้ำเสร็จเรียบร้อย",tail:"เอาไว้มาอาบอีกน๊าาา"}:{title:"นวดตัวสัตว์",image:"dog-massage-status.png?v=1",done:"นวดตัวเสร็จเรียบร้อย",tail:"เอาไว้แวะมาหาหนูอีกน๊า แม่ๆ"}}
  function dogCareState(type,pen=currentDogHotelPen,s=ownState||state){s=normalizeState(s,currentMember);resetDailyExtras(s);return s.dogCare[`pen${pen}`][type]}
  function showDogCare(type,pen=currentDogHotelPen){const a=dogCareState(type,pen),m=careMeta(type),now=NOW();if(a.finishAt>now)return dogCareStatus(type,pen);if(a.finishAt&&a.finishAt<=now&&!a.claimed)return dogCareResult(type,pen);if(a.count>=4)return message(m.title,"วันนี้ทำครบ 4 ครั้งแล้วค่ะ");if(a.cooldownUntil>now)return message(m.title,`ตอนนี้ยังไม่สามารถ${m.title} ได้อีก<br>กลับมาใหม่ใน ${fmt(a.cooldownUntil-now)}`);const count=dogsInHotelPen(pen).length+(ownState?.cats||[]).filter(c=>c.placedHotel&&Number((ownState?.hotelPetPenMap?.[String(c.id)]||c.hotelPen||1))===Number(pen)).length;if(!count)return message(m.title,"คอกนี้ยังไม่มีน้องหมาหรือน้องแมว");$("modalContent").innerHTML=`<section class="feature-panel ynu-dog-care"><img src="${m.image}" alt="${m.title}"><h2>${m.title}</h2><p>สัตว์ในคอก ${pen} จำนวน ${count} ตัว<br>ใช้เวลา 5 นาที</p><button id="ynuStartDogCare">เริ่ม${m.title}</button></section>`;$("ynuStartDogCare").onclick=()=>startDogCare(type,pen);openModal()}
  async function startDogCare(type,pen){try{const s=normalizeState(cloneData(ownState||state),currentMember);resetDailyExtras(s);const a=s.dogCare[`pen${pen}`][type],t=NOW();if(a.count>=4)throw new Error("วันนี้ทำครบ 4 ครั้งแล้ว");if(a.cooldownUntil>t)throw new Error("ตอนนี้ยังไม่สามารถทำได้อีก");const dogs=dogsInHotelPen(pen,s),cats=(s.cats||[]).filter(c=>c.placedHotel&&Number((s.hotelPetPenMap?.[String(c.id)]||c.hotelPen||1))===Number(pen)),pets=dogs.concat(cats);if(!pets.length)throw new Error("คอกนี้ยังไม่มีน้องหมาหรือน้องแมว");const reward=pets.reduce(n=>n+rand(3,10),0);a.startedAt=t;a.finishAt=t+5*MIN;a.reward=reward;a.claimed=false;a.count++;a.cooldownUntil=a.finishAt+2*HOUR;ownState=s;state=s;saveLocalOnly(s);try{save()}catch(_){}dogCareStatus(type,pen)}catch(e){message("เริ่มไม่ได้",e.message||"กรุณาลองใหม่")}}
  function dogCareStatus(type,pen){const a=dogCareState(type,pen),m=careMeta(type);$("modalContent").innerHTML=`<section class="feature-panel ynu-dog-care ynu-dog-care-status"><img src="${m.image}" alt="${m.title}"><h2>${m.title}</h2><p>กำลัง${m.title}...</p><strong id="ynuDogCareTimer">${fmt(a.finishAt-NOW())}</strong><small>ออกไปทำอย่างอื่นหรือออกจากเกมได้ เวลายังคงนับต่อ</small></section>`;openModal();const t=setInterval(()=>{const x=dogCareState(type,pen);if(x.finishAt<=NOW()){clearInterval(t);dogCareResult(type,pen)}else if($("ynuDogCareTimer"))$("ynuDogCareTimer").textContent=fmt(x.finishAt-NOW());else clearInterval(t)},1000)}
  function dogCareResult(type,pen){const a=dogCareState(type,pen),m=careMeta(type);$("modalContent").innerHTML=`<section class="feature-panel ynu-dog-care"><img src="${m.image}" alt="${m.title}"><h2>${m.done}</h2><strong>ได้รับ +${a.reward} กุศล</strong><p>${m.tail}</p><button id="ynuClaimDogCare">รับกุศล</button></section>`;$("ynuClaimDogCare").onclick=()=>claimDogCare(type,pen);openModal()}
  /* R34.9.2: expose the existing hotel-care flow for later hotel renderers.
     R32.9 lives in a different IIFE, so direct showDogCare(...) calls there
     were ReferenceError'd and silently caught, making Bath/Massage look dead. */
  globalThis.YN_DOG_CARE_SHOW=(type,pen)=>showDogCare(type,pen);
  async function claimDogCare(type,pen){try{const s=normalizeState(cloneData(ownState||state),currentMember),a=s.dogCare[`pen${pen}`][type];if(a.claimed||!a.finishAt||a.finishAt>NOW())throw new Error("ยังไม่มีรางวัลให้รับ");const reward=Number(a.reward)||0;s.merit=Number(s.merit||0)+reward;a.claimed=true;a.startedAt=0;a.finishAt=0;a.reward=0;if(currentMember==="Aida"&&adminProfile?.role==="admin")ensureAdminStock(s);ownState=s;state=s;saveLocalOnly(s);updateMeritUI();try{save()}catch(_){}closeModal();showWeatherToast(`🙏 รับ +${reward} กุศลแล้ว`)}catch(e){message("รับไม่ได้",e.message||"กรุณาลองใหม่")}}
  const _renderDog=renderDogHotelScene;renderDogHotelScene=function(){const r=_renderDog();if(currentScene!=="dogHotel")return r;const layer=$("sceneInteractiveLayer");if(layer&&!$("ynuDogBathBtn")){layer.insertAdjacentHTML("beforeend",`<div class="ynu-dog-care-buttons"><button id="ynuDogBathBtn" title="อาบน้ำสัตว์">💧</button><button id="ynuDogMassageBtn" title="นวดตัวสัตว์">🖐️</button></div>`);$("ynuDogBathBtn").onclick=()=>showDogCare("bath",currentDogHotelPen);$("ynuDogMassageBtn").onclick=()=>showDogCare("massage",currentDogHotelPen)}return r};

  /* ---------- Wiman dog coming soon ---------- */
  function bindDogPalace(){const b=$("shortcutDogPalaceBtn");if(b)b.onclick=()=>message("🏰 วิมานหมา","โปรดติดตามซีซั่นต่อไป")};setTimeout(bindDogPalace,0);

  /* ---------- Fishing V2: lobby + 3 ponds + 4 docks ---------- */
  const FISH_PONDS={
    1:{name:"บ่อตกปลาของยัยหนู 01",image:"fishing-pond-01-season2.jpeg",pos:[[7,33.5,31,13.5],[63,33.5,31,13.5],[7,55.5,31,13.5],[63,55.5,31,13.5]]},
    2:{name:"บ่อตกปลาของยัยหนู 02",image:"fishing-pond-02-season2.jpeg",pos:[[7,33.5,31,13.5],[63,33.5,31,13.5],[7,55.5,31,13.5],[63,55.5,31,13.5]]},
    3:{name:"บ่อตกปลาของยัยหนู 03",image:"fishing-pond-03-season2.jpeg",pos:[[7,33.5,31,13.5],[63,33.5,31,13.5],[7,55.5,31,13.5],[63,55.5,31,13.5]]}
  };
  let fishPondId=0,fishSlots=[],fishUnsub=null;
  const fishMirrorKeyV2=()=>currentMemberKey?`s2-fishing-v2-active:${currentMemberKey}`:"";
  function loadFishMirrorV2(){try{const raw=localStorage.getItem(fishMirrorKeyV2());if(!raw)return null;const x=JSON.parse(raw);if(!x||x.dateKey!==DAILY_KEY()||Number(x.claimDeadline||0)<=NOW()){localStorage.removeItem(fishMirrorKeyV2());return null}return x}catch(_){return null}}
  function saveFishMirrorV2(x){try{if(x&&String(x.ownerKey||"")===String(fishingActorKey()))localStorage.setItem(fishMirrorKeyV2(),JSON.stringify(x))}catch(_){}}
  function clearFishMirrorV2(){try{localStorage.removeItem(fishMirrorKeyV2())}catch(_){}}
  function stopFishV2(){if(fishUnsub){fishUnsub();fishUnsub=null}fishSlots=[]}
  function fishingAdminBypass(){return currentMember==="Aida"&&adminProfile?.role==="admin"}
  async function persistPondChoice(id){
    if(fishingAdminBypass())return;
    const st=ownState||state;resetDailyExtras(st);
    if(st.fishingDailyChoice.pondId&&st.fishingDailyChoice.pondId!==id)throw new Error("วันนี้เลือกบ่อไปแล้ว");
    if(st.fishingDailyChoice.pondId===id)return;
    const actorKey=(String(currentMemberKey||"")==="mameaw"||String(currentMember||"").toLowerCase()==="mameaw")?"mameaw":currentMemberKey;
    const {db,fs}=await getFirebaseContext(),ref=fs.doc(db,"saves",actorKey);let next;
    await fs.runTransaction(db,async tx=>{
      const snap=await tx.get(ref);if(!snap.exists())throw new Error("ไม่พบเซฟสมาชิก");
      const x=normalizeState(snap.data(),currentMember);resetDailyExtras(x);
      if(x.fishingDailyChoice.pondId&&x.fishingDailyChoice.pondId!==id)throw new Error("วันนี้เลือกบ่อไปแล้ว");
      x.fishingDailyChoice={dateKey:DAILY_KEY(),pondId:id};next=x;
      tx.set(ref,{...cloneData(x),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
    });
    Y26_applyOwnState(next);saveLocalOnly(ownState||state);
  }
  function openFishingLobby(){
    stopFishV2();fishPondId=0;currentScene="fishingLobby";
    const ynLayer=$("sceneInteractiveLayer");if(ynLayer){ynLayer.onpointerdown=null;delete ynLayer.dataset.r17HouseMode;}
    $("gameScreen").classList.add("hidden");$("sceneScreen").classList.remove("hidden");$("sceneScreen").classList.add("ynu-fishing-lobby-scene");
    $("sceneScreen").style.backgroundImage='url("fishing-lobby-season2.jpeg")';
    setSceneNav({backText:"กลับไปที่แปลงผัก",backAction:returnToFarm});
    const st=normalizeState(ownState||state,currentMember);resetDailyExtras(st);
    const admin=fishingAdminBypass(),chosen=admin?0:Number(st.fishingDailyChoice.pondId||0);
    $("sceneInteractiveLayer").innerHTML=`<div class="ynu-fishing-welcome">ยินดีต้อนรับเข้าสู่ บ่อตกปลาของยัยหนู</div><div class="ynu-pond-choices">${Object.entries(FISH_PONDS).map(([id,p])=>`<button data-ynu-pond="${id}" ${!admin&&chosen&&Number(id)!==chosen?"disabled":""}><b>บ่อ 0${id}</b><span>${p.name}</span>${admin?'<small>Admin • เข้าได้ทุกบ่อ</small>':chosen===Number(id)?'<small>วันนี้เลือกบ่อนี้แล้ว</small>':chosen?'<small>ล็อกถึง 00:00</small>':""}</button>`).join("")}</div><div class="ynu-fishing-lobby-actions"><button id="ynuCraftBait">คราฟเหยื่อตกปลา</button><button id="ynuFishBoard">แดชบอร์ดน้ำหนักปลาวันนี้</button></div>`;
    document.querySelectorAll("[data-ynu-pond]").forEach(b=>b.onclick=async()=>{
      if(b.disabled||b.dataset.busy==="1")return;const id=Number(b.dataset.ynuPond);b.dataset.busy="1";const old=b.innerHTML;b.classList.add("is-busy");
      if(admin){openFishingPond(id);return}
      b.innerHTML=`<b>บ่อ 0${id}</b><span>กำลังเลือกบ่อ...</span>`;
      try{await persistPondChoice(id);openFishingPond(id)}catch(e){b.dataset.busy="0";b.classList.remove("is-busy");b.innerHTML=old;message("เลือกบ่อไม่ได้",e.message)}
    });
    $("ynuCraftBait").onclick=showFishingBaitCraft;$("ynuFishBoard").onclick=showFishingDashboardV2;
  }
  async function openFishingPond(id){
    $("sceneScreen")?.classList.remove("ynu-fishing-lobby-scene");
    const st=normalizeState(ownState||state,currentMember);resetDailyExtras(st);
    if(!fishingAdminBypass()&&Number(st.fishingDailyChoice.pondId)!==Number(id))return openFishingLobby();
    fishPondId=id;currentScene="fishingPondV2";const ynLayer=$("sceneInteractiveLayer");if(ynLayer){ynLayer.onpointerdown=null;delete ynLayer.dataset.r17HouseMode;}$("sceneScreen").style.backgroundImage=`url("${FISH_PONDS[id].image}")`;
    setSceneNav({backText:"กลับหน้าล็อบบี้",backAction:openFishingLobby,nextText:"ไปที่แปลงผัก",nextAction:returnToFarm});
    const localActive=loadFishMirrorV2();if(localActive&&Number(localActive.pondId)===Number(id))fishSlots[Number(localActive.slot)-1]=localActive;
    const savedActive=(ownState||state)?.fishingActiveSession;if(savedActive&&Number(savedActive.claimDeadline||0)>NOW()&&Number(savedActive.pondId)===Number(id)){fishSlots[Number(savedActive.slot)-1]=savedActive;saveFishMirrorV2(savedActive)}
    drawFishingV2();subscribeFishV2();
    /* Server recovery: returning from another app must restore the same cast even if
       the in-app browser discarded timers/local mirror. */
    getFirebaseContext().then(async({db,fs})=>{try{const ref=fs.doc(db,"saves",fishingActorKey()),snap=await fs.getDoc(ref);if(!snap.exists())return;const a=snap.data()?.fishingActiveSession;if(a&&Number(a.claimDeadline||0)>NOW()&&Number(a.pondId)===Number(id)){fishSlots[Number(a.slot)-1]=a;saveFishMirrorV2(a);if(currentScene==="fishingPondV2")drawFishingV2()}}catch(e){console.warn("R34.57 fishing recovery",e)}});
  }
  function slotDocId(pond,slot){return `${DAILY_KEY()}-p${pond}-s${slot}`}
  function subscribeFishV2(){
    stopFishV2();
    getFirebaseContext().then(({db,fs})=>{
      /* Only listen to today's fishing documents. This keeps the pond fast even after
         many days/players have accumulated in fishingSlotsV2. */
      const q=fs.query(fs.collection(db,"fishingSlotsV2"),fs.where("dateKey","==",DAILY_KEY()));
      fishUnsub=fs.onSnapshot(q,snap=>{
        fishSlots=[];
        snap.forEach(d=>{const x=d.data();if(Number(x.pondId)===fishPondId)fishSlots[Number(x.slot)-1]=x});
        const localActive=loadFishMirrorV2();if(localActive&&Number(localActive.pondId)===Number(fishPondId)&&!fishSlots[Number(localActive.slot)-1])fishSlots[Number(localActive.slot)-1]=localActive;
        if(currentScene==="fishingPondV2")drawFishingV2();
      },e=>console.warn("fishing V2 listener",e));
    }).catch(e=>console.warn("fishing V2 subscribe",e));
  }
  function activeSlot(x){return x&&Number(x.claimDeadline||0)>NOW()&&x.status!=="claimed"}
  function drawFishingV2(){if(currentScene!=="fishingPondV2")return;const p=FISH_PONDS[fishPondId];$("sceneInteractiveLayer").innerHTML=p.pos.map(([l,t,w,h],i)=>{const x=fishSlots[i];let text="";if(activeSlot(x)){if(NOW()<x.finishAt)text=`<span>${esc(x.ownerName)} กำลังตกปลา<br>${fmt(x.finishAt-NOW())}</span>`;else text=`<span>ปลาติดเบ็ดแล้ว • รับใน ${fmt(x.claimDeadline-NOW())}</span>`}return `<button class="ynu-fishing-dock" data-ynu-dock="${i+1}" style="left:${l}%;top:${t}%;width:${w}%;height:${h}%">${text}</button>`}).join("");document.querySelectorAll("[data-ynu-dock]").forEach(b=>b.onclick=()=>openFishingDockV2(Number(b.dataset.ynuDock)))}
  function fishingActorKey(){
    return (String(currentMemberKey||"")==="mameaw" || String(currentMember||"").toLowerCase()==="mameaw") ? "mameaw" : currentMemberKey;
  }
  async function getFishingPlayerState(){
    const {db,fs}=await getFirebaseContext();
    const key=fishingActorKey();
    const ref=fs.doc(db,"fishingPlayers",key);
    const snap=await fs.getDoc(ref);
    if(!snap.exists())return null;
    const data=snap.data()||{};
    if(String(key)==="mameaw" && Number(data.claimDeadline||0)<=NOW()){
      try{await fs.deleteDoc(ref);return null}catch(e){console.warn("V210 clear stale Mameaw fishing lock",e)}
    }
    return data;
  }
  async function openFishingDockV2(slotNo){
    const x=fishSlots[slotNo-1],actorKey=fishingActorKey(),dock=document.querySelector(`[data-ynu-dock="${slotNo}"]`);
    if(dock?.dataset.busy==="1")return;
    if(activeSlot(x)){
      /* R35.28: every bait uses the same native Fishing V2 result/claim flow. */
      if(String(x.ownerKey||"")===String(actorKey||"")&&NOW()>=x.finishAt)return fishingResultV2(x);
      return message("แท่นนี้ไม่ว่าง",NOW()<x.finishAt?`${x.ownerName} กำลังตกปลา • เหลือ ${fmt(x.finishAt-NOW())}`:"กำลังรอเจ้าของรับปลา");
    }
    try{
      if(dock){dock.dataset.busy="1";dock.classList.add("is-busy");if(!dock.innerHTML.trim())dock.innerHTML="<span>กำลังตรวจ...</span>"}
      const player=(fishSlots.find(s=>s&&String(s.ownerKey||"")===String(actorKey||"")&&Number(s.claimDeadline||0)>NOW())||null),now=NOW();
      if(player&&Number(player.claimDeadline||0)>now)return message("กำลังตกปลาอยู่","หนึ่งคนตกได้แค่แท่นเดียวในเวลาเดียวกัน");
      const cool=Math.max(Number((ownState||state)?.fishingCooldownUntil||0),player?Number(player.claimDeadline||0)+5*MIN:0);
      if(cool>now)return message("พักก่อน",`ยังตกปลาไม่ได้ • กลับมาใหม่ใน ${fmt(cool-now)}`);
      showFishingBaitChoiceV2(slotNo);
    }catch(e){message("เปิดแท่นไม่ได้",e.message)}
    finally{if(dock?.isConnected){dock.dataset.busy="0";dock.classList.remove("is-busy");if(dock.textContent?.includes("กำลังตรวจ"))dock.innerHTML=""}}
  }
  function showFishingBaitChoiceV2(slotNo){const s=ensureV4State(ownState||state),cards=Object.entries(FISHING_BAITS).map(([k,b])=>`<button data-ynu-fish-bait="${k}" ${Number(s.fishingBaits?.[k]||0)<1?"disabled":""}><img src="${b.image}" alt="${esc(b.name)}"><span>${esc(b.name)}<small>มี ×${Number(s.fishingBaits?.[k]||0)} • ${Math.round(b.durationMs/60000)} นาที</small></span></button>`).join("");$("modalContent").innerHTML=`<section class="feature-panel"><h2>🎣 เลือกเหยื่อตกปลา</h2><div class="ynu-bait-list">${cards}</div></section>`;document.querySelectorAll("[data-ynu-fish-bait]").forEach(b=>b.onclick=()=>{const key=b.dataset.ynuFishBait;if(FISHING_BAITS?.[key]?.r35Special){if(globalThis.YN_R35?.openGimmickSelectorV2)return globalThis.YN_R35.openGimmickSelectorV2(slotNo,key);return message("ระบบเหยื่อใหม่ยังโหลดไม่ครบ","กรุณาออกจากบ่อแล้วเข้าใหม่อีกครั้งค่ะ")}return startFishingV2(slotNo,key)});openModal()}
  async function startFishingV2(slotNo,baitKey){
    const bait=FISHING_BAITS[baitKey];if(!bait)return;
    /* Show the rod immediately. The server transaction below is still the source
       of truth; on failure this optimistic slot is rolled back. */
    const optimisticActor=fishingActorKey(),optimisticNow=NOW(),priorVisual=fishSlots[slotNo-1]||null;
    const optimisticSlot={dateKey:DAILY_KEY(),pondId:fishPondId,slot:slotNo,ownerKey:optimisticActor,ownerName:currentProfileDisplayName(),baitKey,catches:[],totalWeight:0,status:"fishing",startedAt:optimisticNow,finishAt:optimisticNow+bait.durationMs,claimDeadline:optimisticNow+bait.durationMs+5*MIN,__optimistic:true};
    fishSlots[slotNo-1]=optimisticSlot;saveFishMirrorV2(optimisticSlot);drawFishingV2();closeModal();
    try{
      /* The rod is already visible. Finish any queued own-save first so the
         fishing transaction cannot overwrite a newer local farm/inventory save. */
      if(cloudSaveTimer||cloudSaveInFlight)await settlePendingCloudSave();
      const actorKey=fishingActorKey();
      if(String(actorKey)==="mameaw"){
        try{const bridge=await getFirebaseBridge();if(typeof bridge?.forceRefreshToken==="function")await bridge.forceRefreshToken()}catch(e){console.warn("V210 Mameaw fishing token refresh",e)}
      }
      const {db,fs}=await getFirebaseContext(),slotRef=fs.doc(db,"fishingSlotsV2",slotDocId(fishPondId,slotNo)),playerRef=fs.doc(db,"fishingPlayers",actorKey),saveRef=fs.doc(db,"saves",actorKey);

      /* V213: Mameaw uses direct rescue writes. This avoids an all-or-nothing
         multi-document transaction being rejected by one legacy fishing doc. */
      if(actorKey==="mameaw") {
        const now=NOW();
        const [ss,pl,sl]=await Promise.all([fs.getDoc(saveRef),fs.getDoc(playerRef),fs.getDoc(slotRef)]);
        if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");
        const s=normalizeState(ss.data(),currentMember);resetDailyExtras(s);
        if(!fishingAdminBypass()&&s.fishingDailyChoice.pondId!==fishPondId)throw new Error("วันนี้ไม่ได้เลือกบ่อนี้");
        if(pl.exists()&&Number(pl.data().claimDeadline||0)>now)throw new Error("กำลังตกปลาอยู่ที่แท่นอื่น");
        if(pl.exists()&&Number(pl.data().claimDeadline||0)<=now){try{await fs.deleteDoc(playerRef)}catch{}}
        if(Number(s.fishingCooldownUntil||0)>now)throw new Error(`คูลดาวน์เหลือ ${fmt(s.fishingCooldownUntil-now)}`);
        if(sl.exists()&&activeSlot(sl.data()))throw new Error("แท่นนี้ไม่ว่างแล้ว");
        if(Number(s.fishingBaits?.[baitKey]||0)<1)throw new Error("เหยื่อหมดแล้ว");
        s.fishingBaits[baitKey]-=1;
        const roll=rollFishingCatches(baitKey),finish=now+bait.durationMs;
        const directSlot={dateKey:DAILY_KEY(),pondId:fishPondId,slot:slotNo,ownerKey:"mameaw",ownerName:currentProfileDisplayName(),baitKey,catches:roll.catches,totalWeight:roll.total,status:"fishing",startedAt:now,finishAt:finish,claimDeadline:finish+5*MIN};
        s.fishingActiveSession={...directSlot,savedAt:now};
        await fs.setDoc(saveRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
        await fs.setDoc(slotRef,{...directSlot,updatedAt:fs.serverTimestamp()},{merge:false});
        await fs.setDoc(playerRef,{memberKey:"mameaw",pondId:fishPondId,slot:slotNo,finishAt:finish,claimDeadline:finish+5*MIN,updatedAt:fs.serverTimestamp()},{merge:false});
        Y26_applyOwnState(s);fishSlots[slotNo-1]=directSlot;saveFishMirrorV2(directSlot);drawFishingV2();closeModal();showWeatherToast(`🎣 เริ่มตกปลาแล้ว • ${Math.round(bait.durationMs/60000)} นาที`);
        return;
      }

      let next,newSlot;
      await fs.runTransaction(db,async tx=>{
        const [sl,pl,ss]=await Promise.all([tx.get(slotRef),tx.get(playerRef),tx.get(saveRef)]),now=NOW();
        if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");
        const s=normalizeState(ss.data(),currentMember);resetDailyExtras(s);
        if(!fishingAdminBypass()&&s.fishingDailyChoice.pondId!==fishPondId)throw new Error("วันนี้ไม่ได้เลือกบ่อนี้");
        if(pl.exists()&&Number(pl.data().claimDeadline||0)>now)throw new Error("กำลังตกปลาอยู่ที่แท่นอื่น");
        if(Number(s.fishingCooldownUntil||0)>now)throw new Error(`คูลดาวน์เหลือ ${fmt(s.fishingCooldownUntil-now)}`);
        if(sl.exists()&&activeSlot(sl.data()))throw new Error("แท่นนี้ไม่ว่างแล้ว");
        if(Number(s.fishingBaits?.[baitKey]||0)<1)throw new Error("เหยื่อหมดแล้ว");
        s.fishingBaits[baitKey]-=1;
        const roll=rollFishingCatches(baitKey),finish=now+bait.durationMs;
        newSlot={dateKey:DAILY_KEY(),pondId:fishPondId,slot:slotNo,ownerKey:actorKey,ownerName:currentProfileDisplayName(),baitKey,catches:roll.catches,totalWeight:roll.total,status:"fishing",startedAt:now,finishAt:finish,claimDeadline:finish+5*MIN};
        s.fishingActiveSession={...newSlot,savedAt:now};
        next=s;
        tx.set(saveRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
        tx.set(slotRef,{...newSlot,updatedAt:fs.serverTimestamp()},{merge:false});
        tx.set(playerRef,{memberKey:actorKey,pondId:fishPondId,slot:slotNo,finishAt:finish,claimDeadline:finish+5*MIN,updatedAt:fs.serverTimestamp()},{merge:false});
      });
      Y26_applyOwnState(next);fishSlots[slotNo-1]=newSlot;saveFishMirrorV2(newSlot);drawFishingV2();closeModal();showWeatherToast(`🎣 เริ่มตกปลาแล้ว • ${Math.round(bait.durationMs/60000)} นาที`);
    }catch(e){
      if(fishSlots[slotNo-1]?.__optimistic){fishSlots[slotNo-1]=priorVisual;if(!priorVisual)clearFishMirrorV2()}
      drawFishingV2();
      message("เริ่มตกไม่ได้",e.message||"กรุณาลองใหม่")
    }
  }
  function fishingResultV2(x){
    const expired=NOW()>Number(x.claimDeadline||0);
    if(expired)return message("🐟 ปลาได้หนีไปแล้ว","ปลาได้หนีไปแล้ว (แท่นตกปลานี้ว่าง)");
    const catches=Array.isArray(x.catches)?x.catches:[];
    $("modalContent").innerHTML=`<section class="feature-panel"><h2>🎣 ปลาติดเบ็ดแล้ว</h2><div class="fishing-result-grid">${catches.map(c=>`<article class="fishing-result-card"><img src="${c.image||""}"><h3>${esc(c.name||"ปลา")}</h3><small>${Number(c.weight||0)>=0?"+":""}${Number(c.weight||0).toFixed(2)} lbs</small></article>`).join("")}</div><div class="fishing-total-weight">น้ำหนักรวม ${Number(x.totalWeight||0)>=0?"+":""}${Number(x.totalWeight||0).toFixed(2)} lbs</div><p>รับภายใน ${fmt(x.claimDeadline-NOW())}</p><button id="ynuClaimFish">รับปลา</button></section>`;
    $("ynuClaimFish").onclick=()=>claimFishingV2(x);
    openModal();
  }
  async function claimFishingV2(x){
    try{
      const actorKey=(String(currentMemberKey||"")==="mameaw"||String(currentMember||"").toLowerCase()==="mameaw")?"mameaw":currentMemberKey;
      if(actorKey==="mameaw"){try{const bridge=await getFirebaseBridge();if(typeof bridge?.forceRefreshToken==="function")await bridge.forceRefreshToken()}catch(e){console.warn("V211 Mameaw claim token refresh",e)}}
      const {db,fs}=await getFirebaseContext();
      const slotRef=fs.doc(db,"fishingSlotsV2",slotDocId(x.pondId,x.slot));
      const playerRef=fs.doc(db,"fishingPlayers",actorKey);
      const saveRef=fs.doc(db,"saves",actorKey);
      const dailyRef=fs.doc(db,"fishingDaily",DAILY_KEY());
      let next=null,claimedWeight=0;

      /* V213 direct Mameaw claim: save + daily first, cleanup after. */
      if(actorKey==="mameaw") {
        const [sl,ss,dd]=await Promise.all([fs.getDoc(slotRef),fs.getDoc(saveRef),fs.getDoc(dailyRef)]);
        if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");
        const slot=sl.exists()?sl.data():x;
        if(String(slot.ownerKey||"")!=="mameaw")throw new Error("รอบตกปลานี้ไม่ตรงกับบัญชีมะเหมี่ยว");
        if(NOW()<Number(slot.finishAt||x.finishAt||0))throw new Error("ปลายังไม่ติดเบ็ด");
        if(NOW()>Number(slot.claimDeadline||x.claimDeadline||0))throw new Error("ปลาได้หนีไปแล้ว");
        const s=normalizeState(ss.data(),currentMember);
        const d=dd.exists()?dd.data():{dateKey:DAILY_KEY(),scores:{},names:{},ponds:{}};
        d.scores=ensureObj(d.scores);d.names=ensureObj(d.names);d.ponds=ensureObj(d.ponds);
        const receipt=`${DAILY_KEY()}:${x.pondId}:${x.slot}:${Number(slot.startedAt||x.startedAt||0)}`;
        s.fishingClaimReceipts=ensureObj(s.fishingClaimReceipts);
        if(s.fishingClaimReceipts[receipt])throw new Error("รับน้ำหนักรอบนี้แล้ว");
        claimedWeight=Number(Number(slot.totalWeight||x.totalWeight||0).toFixed(2));
        d.scores.mameaw=Number((Number(d.scores.mameaw||0)+claimedWeight).toFixed(2));
        d.names.mameaw=currentProfileDisplayName();d.ponds.mameaw=Number(x.pondId||0);
        ensureMissionStateFor(s);s.missions.progress.dailyFishingWeight500=d.scores.mameaw;s.missions.progress.dailyFishingWeight500=d.scores.mameaw;
        s.fishingCooldownUntil=NOW()+5*MIN;s.fishingClaimReceipts[receipt]=NOW();s.fishingActiveSession=null;
        await fs.setDoc(saveRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
        await fs.setDoc(dailyRef,{dateKey:DAILY_KEY(),scores:d.scores,names:d.names,ponds:d.ponds,updatedAt:fs.serverTimestamp()},{merge:false});
        try{await fs.updateDoc(slotRef,{status:"claimed",claimedAt:NOW(),claimDeadline:NOW(),updatedAt:fs.serverTimestamp()})}catch(e){console.warn("V213 mameaw slot cleanup",e)}
        try{await fs.deleteDoc(playerRef)}catch(e){console.warn("V213 mameaw player cleanup",e)}
        Y26_applyOwnState(s);try{await globalThis.YN_S2_CAMPAIGNS?.scoreFishingClaim?.(slot,`fish-v2:${actorKey}:${Number(slot.startedAt||x.startedAt||0)}:${x.pondId}:${x.slot}`)}catch(e){console.warn("R36 fishing campaign score",e)}closeModal();showWeatherToast(`🏆 รับ ${claimedWeight.toFixed(2)} lbs เข้าดashboardแล้ว • คูลดาวน์ 5 นาที`);
        return;
      }

      /*
        V194:
        The old function caught its own permission error, so the V193 wrapper
        never received an exception and its fallback never ran.
        This is now fixed directly in the original claim function.
      */
      await fs.runTransaction(db,async tx=>{
        const [sl,ss,dd]=await Promise.all([
          tx.get(slotRef),
          tx.get(saveRef),
          tx.get(dailyRef)
        ]);

        if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");

        const slot=sl.exists()?sl.data():x;
        const canonical=actorKey||memberKeyFromName(currentMember||"");
        const ownerOk=
          !sl.exists()
          || String(slot.ownerKey||"")===String(actorKey||"")
          || String(slot.ownerKey||"")===String(canonical||"")
          || String(slot.ownerName||"").trim().toLowerCase()
             ===String(currentMember||"").trim().toLowerCase();

        if(!ownerOk)throw new Error("รอบตกปลานี้ไม่ตรงกับบัญชีผู้เล่น");
        if(NOW()>Number(slot.claimDeadline||x.claimDeadline||0))
          throw new Error("ปลาได้หนีไปแล้ว");

        const s=normalizeState(ss.data(),currentMember);
        const d=dd.exists()?dd.data():{dateKey:DAILY_KEY(),scores:{},names:{},ponds:{}};
        d.scores=ensureObj(d.scores);
        d.names=ensureObj(d.names);
        d.ponds=ensureObj(d.ponds);

        const key=canonical||actorKey;
        const receipt=`${DAILY_KEY()}:${x.pondId}:${x.slot}:${Number(slot.startedAt||x.startedAt||0)}`;
        s.fishingClaimReceipts=ensureObj(s.fishingClaimReceipts);
        if(s.fishingClaimReceipts[receipt])throw new Error("รับน้ำหนักรอบนี้แล้ว");

        claimedWeight=Number(Number(slot.totalWeight||x.totalWeight||0).toFixed(2));
        d.scores[key]=Number((Number(d.scores[key]||0)+claimedWeight).toFixed(2));
        d.names[key]=currentProfileDisplayName();
        d.ponds[key]=Number(x.pondId||0);

        ensureMissionStateFor(s);
        s.missions.progress.dailyFishingWeight500=d.scores[key];
        s.missions.progress.dailyFishingWeight500=d.scores[key];
        s.fishingCooldownUntil=NOW()+5*MIN;
        s.fishingClaimReceipts[receipt]=NOW();
        s.fishingActiveSession=null;
        next=s;

        tx.set(saveRef,{
          ...cloneData(s),
          activeSessionId:cloudSessionId,
          updatedAt:fs.serverTimestamp()
        },{merge:false});

        tx.set(dailyRef,{
          dateKey:DAILY_KEY(),
          scores:d.scores,
          names:d.names,
          ponds:d.ponds,
          updatedAt:fs.serverTimestamp()
        },{merge:false});
      });

      Y26_applyOwnState(next);
      try{await globalThis.YN_S2_CAMPAIGNS?.scoreFishingClaim?.(x,`fish-v2:${actorKey}:${Number(x?.startedAt||0)}:${x?.pondId}:${x?.slot}`)}catch(e){console.warn("R36 fishing campaign score",e)}

      /* Cleanup is best-effort only. A slot/player permission issue can no
         longer cancel the fish weight already credited to save + dashboard. */
      try{
        await fs.updateDoc(slotRef,{
          status:"claimed",
          claimedAt:NOW(),
          claimDeadline:NOW(),
          updatedAt:fs.serverTimestamp()
        });
      }catch(e){console.warn("V194 slot cleanup",e)}
      try{await fs.deleteDoc(playerRef)}catch(e){console.warn("V194 player cleanup",e)}

      closeModal();
      showWeatherToast(`🏆 รับ ${claimedWeight.toFixed(2)} lbs เข้าดashboardแล้ว • คูลดาวน์ 5 นาที`);
    }catch(e){
      console.error("V194 claim fish",e);
      message("รับปลาไม่ได้",e.message||"กรุณาลองใหม่");
    }
  }
  async function showFishingDashboardV2(){
    $("modalContent").innerHTML=`<section class="feature-panel fishing-dashboard-panel"><h2>🏆 แดชบอร์ดน้ำหนักปลาวันนี้</h2><div class="ynu-dashboard-loading">กำลังอ่านคะแนน...</div></section>`;openModal();
    try{
      const {db,fs}=await getFirebaseContext();
      const [snap,dirSnap]=await Promise.all([
        fs.getDoc(fs.doc(db,"fishingDaily",DAILY_KEY())),
        fs.getDocs(fs.collection(db,"loginDirectory"))
      ]);
      const d=snap.exists()?snap.data():{scores:{},names:{},ponds:{}};
      const byKey=new Map();
      Object.keys(MEMBERS).filter(n=>n!=="Aida").forEach(name=>byKey.set(memberKeyFromName(name),name));
      dirSnap.forEach(docSnap=>{const row=docSnap.data()||{},key=String(row.memberKey||docSnap.id||"");if(key&&key!=="aida")byKey.set(key,String(row.displayName||key))});
      Object.keys(d.scores||{}).forEach(key=>{if(!byKey.has(key))byKey.set(key,String(d.names?.[key]||key))});
      const rows=[...byKey].map(([key,name])=>({name,key,weight:Number(d.scores?.[key]||0),pond:Number(d.ponds?.[key]||0)})).sort((a,b)=>b.weight-a.weight||a.name.localeCompare(b.name,"th"));
      $("modalContent").innerHTML=`<section class="feature-panel fishing-dashboard-panel"><h2>🏆 แดชบอร์ดน้ำหนักปลาวันนี้</h2><div class="ynu-score-table ynu-score-table-scroll"><div class="head"><b>อันดับ</b><b>ชื่อ</b><b>บ่อ</b><b>น้ำหนัก</b></div>${rows.map((r,i)=>`<div><span>${i+1}</span><span>${esc(r.name)}</span><span>${r.pond?`บ่อ 0${r.pond}`:"-"}</span><strong>${r.weight.toFixed(2)}</strong></div>`).join("")}</div></section>`;
    }catch(e){$("modalContent").innerHTML=`<section class="feature-panel fishing-dashboard-panel"><h2>แดชบอร์ด</h2><p>อ่านข้อมูลไม่สำเร็จ</p></section>`;message("เปิดแดชบอร์ดไม่ได้",e.message)}
  }

  /* ---------- Jellyfish pond 2 ---------- */
  let jelly2Cache=null,jelly2Unsub=null;
  function emptyJ2(){return{slots:Array(12).fill(null)}}
  function normJ2(d){const now=NOW(),slots=Array.isArray(d?.slots)?d.slots.slice(0,12):[];while(slots.length<12)slots.push(null);return{slots:slots.map(x=>{if(!x||typeof x!=="object")return null;if(Number(x.expiresAt||0)<=now)return null;const n={...x,version:Number(x.version)||1,feedCount:Math.max(0,Math.min(5,Number(x.feedCount)||0)),cooldownUntil:Number(x.cooldownUntil)||0};if(Number(n.version)===1&&n.cooldownUntil>0&&n.cooldownUntil<=now){n.cooldownUntil=0;n.feedCount=0}if(Number(n.version)===2&&n.cooldownUntil<=now)n.cooldownUntil=0;return n})}}
  function stopJ2(){if(jelly2Unsub){jelly2Unsub();jelly2Unsub=null}}
  async function openJelly2(){
    $("sceneScreen")?.classList.remove("ynu-fishing-lobby-scene");if(jellyPondUnsubscribe)stopJellyPondSubscription();
    currentScene="jellyfish2";$("gameScreen").classList.add("hidden");$("sceneScreen").classList.remove("hidden");
    $("sceneScreen").style.backgroundImage='url("jellyfish-season2-pond.jpeg")';
    setSceneNav({backText:"กลับไปที่แปลง",backAction:returnToFarm});
    drawJ2();
    try{
      const {db,fs}=await getFirebaseContext(),ref=fs.doc(db,"shared","jellyfishPond2");
      if(jelly2Unsub)jelly2Unsub();
      jelly2Unsub=fs.onSnapshot(ref,async s=>{
        if(!s.exists()){try{await fs.setDoc(ref,{slots:Array(12).fill(null),updatedAt:fs.serverTimestamp()},{merge:false})}catch{};return}
        jelly2Cache=normJ2(s.data());if(currentScene==="jellyfish2")drawJ2();
      },e=>console.warn("jelly2 listener",e));
    }catch(e){console.warn("open jelly2",e)}
  }
  function jtype(slot){return Number(slot.version)===2?(Y26_JELLY_V2[slot.typeKey]||{}):(JELLYFISH_TYPES[slot.typeKey]||{})}
  function drawJ2(){if(currentScene!=="jellyfish2")return;const slots=jelly2Cache?.slots||Array(12).fill(null);$("sceneInteractiveLayer").innerHTML=`<div class="jelly-pond-banner">🪼 บ่อแมงกะพรุน 2 • ${slots.filter(Boolean).length}/12</div>${JELLY_SLOT_POSITIONS.map(([l,t],i)=>{const x=slots[i];if(!x)return `<button class="jelly-slot jelly-slot-empty" data-j2="${i}" style="left:${l}%;top:${t}%"></button>`;const ty=jtype(x),v2=Number(x.version)===2,ready=!v2&&Number(x.feedCount||0)>=5&&Number(x.cooldownUntil||0)<=NOW(),cool=Number(x.cooldownUntil||0)>NOW();return `<button class="jelly-slot jelly-slot-owned ${v2?"jelly-v2-slot":""} ${ready?"jelly-ready-love":""}" data-j2="${i}" style="left:${l}%;top:${t}%"><img src="${ty.image}" alt="${esc(ty.name)}"><small>${esc(x.customName||ty.name)}<br>${Math.max(0,Math.ceil((x.expiresAt-NOW())/HOUR))} ชม. • ${v2?(cool?"คูลดาวน์":"พร้อมให้อาหาร"):(cool?"คูลดาวน์":ready?"พร้อมท้ารัก":`${x.feedCount||0}/5`)}</small></button>`}).join("")}`;document.querySelectorAll("[data-j2]").forEach(b=>b.onclick=()=>j2Slot(Number(b.dataset.j2)))}
  function j2Slot(i){const x=jelly2Cache?.slots?.[i];if(!x)return j2PlacePicker(i);j2Details(i,x)}
  function j2PlacePicker(i){const s=ownState||state,choices=[...Object.entries(Y26_JELLY_V2).filter(([k])=>Number(s.jellyfishV2?.[k]||0)>0).map(([k,v])=>({version:2,key:k,...v,count:s.jellyfishV2[k]}))];if(!choices.length)return message("ยังไม่มีแมงกะพรุน","ต้องมีแมงกะพรุนในกระเป๋าก่อน");$("modalContent").innerHTML=`<section class="feature-panel"><h2>🪼 เลือกแมงกะพรุนลงบ่อ 2</h2><div class="jelly-picker-grid">${choices.map(x=>`<button data-j2-place="${x.version}:${x.key}"><img src="${x.image}"><b>${esc(x.name)}</b><small>V${x.version} • มี ×${x.count}</small></button>`).join("")}</div></section>`;document.querySelectorAll("[data-j2-place]").forEach(b=>{const [v,k]=b.dataset.j2Place.split(":");b.onclick=()=>j2Place(i,k,Number(v))});openModal()}
  async function j2Place(i,key,version){try{const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2"),sRef=fs.doc(db,"saves",currentMemberKey);let next;await fs.runTransaction(db,async tx=>{const [ps,ss]=await Promise.all([tx.get(pRef),tx.get(sRef)]),p=normJ2(ps.data()),s=normalizeState(ss.data(),currentMember);if(p.slots[i])throw new Error("ช่องนี้ไม่ว่างแล้ว");if(version===2){if(Number(s.jellyfishV2?.[key]||0)<1)throw new Error("แมงกะพรุนหมดแล้ว");s.jellyfishV2[key]--}else{if(Number(s.specialAnimals?.[key]||0)<1)throw new Error("แมงกะพรุนหมดแล้ว");s.specialAnimals[key]--}const now=NOW();p.slots[i]={id:crypto.randomUUID?.()||`${currentMemberKey}-${now}`,version,typeKey:key,ownerKey:currentMemberKey,ownerName:currentProfileDisplayName(),customName:"",placedAt:now,expiresAt:now+(version===2?Y26_JELLY_V2_LIFETIME_MS:JELLY_LIFETIME_MS),feedCount:0,cooldownUntil:0};next=s;tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false})});Y26_applyOwnState(next);closeModal()}catch(e){message("วางไม่ได้",e.message)}}
  function j2Details(i,x){
    const ty=jtype(x),isOwner=x.ownerKey===currentMemberKey,cooldown=Math.max(0,Number(x.cooldownUntil||0)-NOW()),lax=Number((ownState||state)?.specials?.jellyfishLaxative||0);
    if(Number(x.version)===2){
      $("modalContent").innerHTML=`<section class="feature-panel jelly-detail-panel"><img class="jelly-detail-img" src="${ty.image}" alt="${esc(ty.name)}"><h2>${esc(x.customName||ty.name)}</h2><p><b>เวอร์ชัน:</b> V2<br><b>เจ้าของ:</b> ${esc(x.ownerName||"ผู้เล่น")}<br><b>อายุคงเหลือ:</b> ${Math.max(0,Math.ceil((x.expiresAt-NOW())/HOUR))} ชั่วโมง<br>${cooldown>0?`<b>ให้อาหารได้อีก:</b> ${fmt(cooldown)}`:"<b>พร้อมให้อาหารแล้ว</b>"}</p><div class="jelly-action-grid"><button id="j2FeedV2" type="button" ${cooldown>0?"disabled":""}>🍽️ ให้อาหาร</button>${isOwner?'<button id="j2Rename">✏️ ตั้งชื่อ</button>':""}</div><p class="feature-subtitle">V2 ใช้กติกาเดียวกับบ่อ 1 • ไม่สามารถถูกวางยาถ่ายได้</p></section>`;
      $("j2FeedV2").onclick=()=>j2FeedV2(i);
      if($("j2Rename"))$("j2Rename").onclick=()=>j2Rename(i);
      openModal();return;
    }
    const ready=Number(x.feedCount)>=5&&cooldown<=0;
    $("modalContent").innerHTML=`<section class="feature-panel jelly-detail-panel"><img class="jelly-detail-img" src="${ty.image}" alt="${esc(ty.name)}"><h2>${esc(x.customName||ty.name)}</h2><p><b>เวอร์ชัน:</b> V1<br><b>เจ้าของ:</b> ${esc(x.ownerName||"ผู้เล่น")}<br><b>อายุคงเหลือ:</b> ${Math.max(0,Math.ceil((x.expiresAt-NOW())/HOUR))} ชั่วโมง<br><b>อาหาร:</b> ${Number(x.feedCount||0)}/5${cooldown>0?`<br><b>คูลดาวน์:</b> ${fmt(cooldown)}`:""}</p><div class="jelly-action-grid"><button id="j2FeedV1" type="button" ${ready||cooldown>0?"disabled":""}>🍽️ ให้อาหาร</button>${ready&&isOwner?'<button id="j2Love">💞 ท้ารัก</button>':""}${isOwner?'<button id="j2Rename">✏️ ตั้งชื่อ</button>':`<button id="j2Poison" class="danger-action" ${lax<1?"disabled":""}>🧪 ใช้ยาถ่าย ×1</button>`}</div></section>`;
    if($("j2FeedV1"))$("j2FeedV1").onclick=()=>j2FeedV1(i);
    if($("j2Love"))$("j2Love").onclick=()=>claimJ2Love(i);
    if($("j2Rename"))$("j2Rename").onclick=()=>j2Rename(i);
    if($("j2Poison"))$("j2Poison").onclick=()=>poisonJ2(i);
    openModal();
  }

  async function j2Rename(i){
    const x=jelly2Cache?.slots?.[i];if(!x||x.ownerKey!==currentMemberKey)return message("ตั้งชื่อไม่ได้","เฉพาะเจ้าของแมงกะพรุนเท่านั้น");
    const ty=jtype(x),typed=window.prompt("ตั้งชื่อแมงกะพรุน",x.customName||ty.name);if(typed===null)return;const clean=typed.trim().slice(0,20);
    try{const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2");await fs.runTransaction(db,async tx=>{const ps=await tx.get(pRef),p=normJ2(ps.data()),q=p.slots[i];if(!q||q.ownerKey!==currentMemberKey)throw new Error("คุณไม่ใช่เจ้าของ");q.customName=clean;tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false})});closeModal();showWeatherToast("✏️ เปลี่ยนชื่อแมงกะพรุนแล้ว")}catch(e){message("ตั้งชื่อไม่ได้",e.message||"กรุณาลองใหม่")}
  }

  function j2FeedV1(i){
    const s=ownState||state,plankton=Number(s?.bag?.hauntedPlankton)||0,truffle=Number(s?.animalProducts?.truffle)||0;
    $("modalContent").innerHTML=`<section class="feature-panel jelly-food-panel"><h2>🍽️ เลือกอาหารแมงกะพรุน</h2><p class="feature-subtitle">บ่อ 2 ใช้กติกาเดียวกับบ่อ 1 • ให้อาหารสำเร็จ +1 กุศล</p><div class="jelly-food-grid"><button data-j2-v1-food="plankton" ${plankton<1?"disabled":""}><b>แพลงก์ตอนหลอนปิ๊ ×1</b><small>มี ×${plankton}</small></button><button data-j2-v1-food="truffle" ${truffle<2?"disabled":""}><b>เห็ดทรัฟเฟิล ×2</b><small>มี ×${truffle}</small></button></div></section>`;
    document.querySelectorAll("[data-j2-v1-food]").forEach(b=>b.onclick=()=>commitJ2V1(i,b.dataset.j2V1Food));openModal();
  }

  async function commitJ2V1(i,foodType){
    try{
      const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2"),sRef=fs.doc(db,"saves",currentMemberKey),prof=fs.doc(db,"publicProfiles",currentMemberKey);let next;
      await fs.runTransaction(db,async tx=>{
        const [ps,ss]=await Promise.all([tx.get(pRef),tx.get(sRef)]),p=normJ2(ps.data()),s=normalizeState(ss.data(),currentMember),x=p.slots[i];
        if(!x||Number(x.version)!==1)throw new Error("ไม่พบแมงกะพรุน V1");
        if(Number(x.cooldownUntil||0)>NOW())throw new Error(`ยังอยู่ในคูลดาวน์ ${fmt(x.cooldownUntil-NOW())}`);
        if(Number(x.feedCount||0)>=5)throw new Error("แมงกะพรุนอิ่มครบ 5/5 แล้ว");
        if(foodType==="truffle"){if(Number(s.animalProducts?.truffle||0)<2)throw new Error("เห็ดทรัฟเฟิลไม่ครบ 2 ชิ้น");s.animalProducts.truffle-=2}
        else{if(Number(s.bag?.hauntedPlankton||0)<1)throw new Error("ไม่มีแพลงก์ตอนหลอนปิ๊");s.bag.hauntedPlankton-=1}
        s.merit=Number(s.merit||0)+1;x.feedCount=Math.min(5,Number(x.feedCount||0)+1);incrementMissionOn(s,"feedJellyfish",1);next=s;
        tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
        tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false});
        tx.set(prof,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),merit:s.merit,updatedAt:fs.serverTimestamp()},{merge:true});
      });
      Y26_applyOwnState(next);updateMeritUI();closeModal();showWeatherToast("🍽️ ให้อาหารบ่อ 2 สำเร็จ • +1 กุศล");
    }catch(e){message("ให้อาหารไม่ได้",e.message||"กรุณาลองใหม่")}
  }

  async function claimJ2Love(i){try{const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2"),sRef=fs.doc(db,"saves",currentMemberKey),prof=fs.doc(db,"publicProfiles",currentMemberKey);let next,rewardText="";await fs.runTransaction(db,async tx=>{const [ps,ss]=await Promise.all([tx.get(pRef),tx.get(sRef)]),p=normJ2(ps.data()),s=normalizeState(ss.data(),currentMember),x=p.slots[i];if(!x||x.ownerKey!==currentMemberKey||x.version!==1||Number(x.feedCount)<5||Number(x.cooldownUntil)>NOW())throw new Error("ยังท้ารักไม่ได้");rewardText=rollJellyLoveReward(s);x.feedCount=5;x.cooldownUntil=NOW()+JELLY_LOVE_COOLDOWN_MS;next=s;tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(prof,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),merit:s.merit,updatedAt:fs.serverTimestamp()},{merge:true})});Y26_applyOwnState(next);updateMeritUI();message("💞 ท้ารักสำเร็จ",rewardText||"ได้รับรางวัลแล้ว") }catch(e){message("ท้ารักไม่ได้",e.message)}}
  async function poisonJ2(i){
    try{
      const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2"),sRef=fs.doc(db,"saves",currentMemberKey);let next,ownerKey="";
      await fs.runTransaction(db,async tx=>{
        const [ps,ss]=await Promise.all([tx.get(pRef),tx.get(sRef)]),p=normJ2(ps.data()),s=normalizeState(ss.data(),currentMember),x=p.slots[i];
        if(!x||Number(x.version)!==1)throw new Error("ยาถ่ายใช้กับแมงกะพรุน V1 เท่านั้น");
        if(x.ownerKey===currentMemberKey)throw new Error("วางยาถ่ายแมงกะพรุนของตัวเองไม่ได้");
        if(Number(s.specials?.jellyfishLaxative||0)<1)throw new Error("ไม่มียาถ่ายแมงกะพรุน");
        s.specials.jellyfishLaxative--;ownerKey=x.ownerKey;x.expiresAt=Math.max(NOW(),Number(x.expiresAt)-JELLY_POISON_REDUCE_MS);if(x.expiresAt<=NOW())p.slots[i]=null;next=s;
        tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
        tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false});
        if(ownerKey)tx.set(fs.doc(fs.collection(db,"mailboxes",ownerKey,"items")),{source:"friend",type:"jellyPoison",fromKey:currentMemberKey,title:"มีคนใช้ยาถ่ายแมงกะพรุนของคุณ 🧪",text:"แมงกะพรุนในบ่อ 2 อายุลดลง 3 ชั่วโมง",read:false,createdAt:fs.serverTimestamp()});
      });
      Y26_applyOwnState(next);closeModal();showWeatherToast("🧪 ใช้ยาถ่ายในบ่อ 2 สำเร็จ • อายุลดลง 3 ชั่วโมง");
    }catch(e){message("วางยาไม่ได้",e.message||"กรุณาลองใหม่")}
  }

  function j2FeedV2(i){const s=ownState||state,plank=Number(s.bag?.hauntedPlankton||0),fish=Number(s.coconutRiverItems?.fish4||0);$("modalContent").innerHTML=`<section class="feature-panel"><h2>🍽️ เลือกอาหาร V2</h2><div class="cat-feed-grid"><button data-j2-v2="plankton" ${plank<50?"disabled":""}>แพลงก์ตอน ×50 • มี ${plank}</button><button data-j2-v2="fish4" ${fish<20?"disabled":""}>ปลาหมายเลข4 ×20 • มี ${fish}</button></div></section>`;document.querySelectorAll("[data-j2-v2]").forEach(b=>b.onclick=()=>commitJ2V2(i,b.dataset.j2V2));openModal()}
  async function commitJ2V2(i,food){try{const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2"),sRef=fs.doc(db,"saves",currentMemberKey),prof=fs.doc(db,"publicProfiles",currentMemberKey);let next,reward=0;await fs.runTransaction(db,async tx=>{const [ps,ss]=await Promise.all([tx.get(pRef),tx.get(sRef)]),p=normJ2(ps.data()),s=normalizeState(ss.data(),currentMember),x=p.slots[i];if(!x||x.version!==2||Number(x.cooldownUntil)>NOW())throw new Error("ให้อาหารไม่ได้");if(food==="fish4"){if(Number(s.coconutRiverItems?.fish4||0)<20)throw new Error("ปลาไม่พอ");s.coconutRiverItems.fish4-=20}else{if(Number(s.bag?.hauntedPlankton||0)<50)throw new Error("แพลงก์ตอนไม่พอ");s.bag.hauntedPlankton-=50}reward=rand(50,150);s.merit=Number(s.merit||0)+reward;x.cooldownUntil=NOW()+Y26_JELLY_V2_COOLDOWN_MS;incrementMissionOn(s,"feedJellyfish",1);next=s;tx.set(sRef,{...cloneData(s),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(prof,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),merit:s.merit,updatedAt:fs.serverTimestamp()},{merge:true})});Y26_applyOwnState(next);updateMeritUI();message("ขอบคุณที่เลี้ยงดูเรา เป็นอย่างดี",`+${reward} กุศล`) }catch(e){message("ให้อาหารไม่ได้",e.message)}}
  const _drawJellyBase=drawJellyfishPond;
  drawJellyfishPond=function(pond){
    const r=_drawJellyBase(pond);
    if(currentScene==="jellyfish"){
      const layer=$("sceneInteractiveLayer");
      if(layer&&!$("ynuJelly2Btn")){
        const b=document.createElement("button");
        b.id="ynuJelly2Btn";
        b.className="ynu-jelly2-button";
        b.type="button";
        b.textContent="ไปบ่อแมงกะพรุน 2";
        b.onclick=()=>openJelly2();
        layer.appendChild(b);
      }
    }
    return r;
  };
  const _renderJelly=renderJellyfishScene;
  renderJellyfishScene=async function(){
    const r=await _renderJelly();
    if(currentScene==="jellyfish"&&jellyPondCache)drawJellyfishPond(jellyPondCache);
    return r;
  };

  /* ---------- Sea boxing arena ---------- */
  const OPP=[
    {name:"เวเนเซีย",image:"01-venezia.png?v=1",mod:15},{name:"พีค็อกกี้",image:"02-peacocky.png?v=1",mod:10},{name:"โรซี่คาวบอย",image:"03-rosie-cowboy.png?v=1",mod:0},{name:"ซากุระฮิเมะ",image:"04-sakura-hime.png?v=1",mod:-5},{name:"หงส์เพลิง",image:"05-hong-phloeng.png?v=1",mod:-10},{name:"ลูนาร่า",image:"06-lunara.png?v=1",mod:-15}
  ];
  const MOVES=[
    {id:1,name:"จระเข้ฟาดหาง",image:"jellyfish-fight-move-01.png?v=2"},
    {id:2,name:"หักงวงไอยรา",image:"jellyfish-fight-move-02.png?v=2"},
    {id:3,name:"หนุมานถวายแหวน",image:"jellyfish-fight-move-03.png?v=2"},
    {id:4,name:"นาคาบิดหาง",image:"jellyfish-fight-move-04.png?v=2"},
    {id:5,name:"จักรนารายณ์",image:"jellyfish-fight-move-05.png?v=2"},
    {id:6,name:"ฤาษีบดยา",image:"jellyfish-fight-move-06.png?v=2"},
    {id:7,name:"กวางเหลียวหลัง",image:"jellyfish-fight-move-07.png?v=2"},
    {id:8,name:"พระรามเดินดง",image:"jellyfish-fight-move-08.png?v=2"}
  ];
  let arenaChoice={jelly:null,opp:null,move:null},arenaFinalizing=false,arenaBoardUnsub=null;
  function thaiHour(){return Number(new Intl.DateTimeFormat("en-US",{timeZone:"Asia/Bangkok",hour:"2-digit",hour12:false}).format(new Date(NOW())))%24}
  function weekKey(){const d=new Date(NOW()+7*HOUR),day=d.getUTCDay(),daysSinceWed=(day+4)%7,wed=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()-daysSinceWed,5,0,0));if(NOW()<wed.getTime())wed.setUTCDate(wed.getUTCDate()-7);return `${wed.getUTCFullYear()}-${String(wed.getUTCMonth()+1).padStart(2,"0")}-${String(wed.getUTCDate()).padStart(2,"0")}`}
  function arenaOutcome(oppIndex,moveId){const h=thaiHour();if([2,13,21].includes(h))return{win:false,score:0};let p=60;const hourMods=[-10,-15,-20,-5,5,10,15,20,10,5,0,-5,10,15,-10,0,10,15,20,10,0,-20,-10,-5];p+=hourMods[h]||0;p+=OPP[oppIndex]?.mod||0;const matchup=((moveId*3+oppIndex*5)%3)-1;p+=matchup*10;p=Math.max(15,Math.min(85,p));const win=Math.random()*100<p;if(!win)return{win:false,score:0};const r=Math.random()*100;const score=r<25?1:r<50?2:r<70?3:r<85?4:r<95?5:6;return{win:true,score}}
  async function placedV2(){const out=[];try{const p1=jellyPondCache||await loadSharedJellyPond();for(const x of p1.slots||[])if(x&&Number(x.version)===2&&x.ownerKey===currentMemberKey)out.push({...x,pond:1,type:jtype(x)});const {db,fs}=await getFirebaseContext(),s=await fs.getDoc(fs.doc(db,"shared","jellyfishPond2")),p2=normJ2(s.exists()?s.data():null);for(const x of p2.slots||[])if(x&&Number(x.version)===2&&x.ownerKey===currentMemberKey)out.push({...x,pond:2,type:jtype(x)})}catch(e){}return out}
  function arenaLegacyResolved(f){return Boolean(f&&(f.scoreClaimed||f.claimed||f.ack))}
  function arenaFightMalformed(f){if(!f||typeof f!=="object")return false;const finish=Number(f.finishAt||0),start=Number(f.startedAt||0);return !finish||!start||typeof f.win!=="boolean"}
  async function syncArenaFromCloud(){
    try{
      await settlePendingCloudSave();
      const {db,fs}=await getFirebaseContext(),ref=fs.doc(db,"saves",currentMemberKey),snap=await fs.getDoc(ref);
      if(!snap.exists())return null;
      const fresh=normalizeState(snap.data(),currentMember);
      if(fresh?.arena?.fight&&(arenaLegacyResolved(fresh.arena.fight)||arenaFightMalformed(fresh.arena.fight))){
        fresh.arena.fight=null;
        await fs.setDoc(ref,{...cloneData(fresh),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
      }
      Y26_applyOwnState(fresh);
      return fresh;
    }catch(e){console.warn("arena cloud sync",e);return ownState||state}
  }
  async function openArena(){return openJelly2()}
  function drawArena(){if(currentScene!=="jellyfishArena")return;$("sceneInteractiveLayer").innerHTML=`<button class="ynu-arena-zone left" id="ynuArenaMine" aria-label="เลือกแมงกะพรุนของเรา"></button><button class="ynu-arena-zone right" id="ynuArenaOpp" aria-label="เลือกคู่แข่ง"></button><div class="ynu-arena-actions"><button id="ynuArenaMove">เลือกท่าต่อสู้</button><button id="ynuArenaStart">เริ่มการต่อสู้</button></div><button id="ynuArenaBoard" class="ynu-arena-board">แดชบอร์ด</button>${arenaChoice.jelly?`<div class="ynu-arena-picked mine"><img src="${arenaChoice.jelly.type.image}"><small>${esc(arenaChoice.jelly.customName||arenaChoice.jelly.type.name)}</small></div>`:""}${arenaChoice.opp!=null?`<div class="ynu-arena-picked opp"><img src="${OPP[arenaChoice.opp].image}"><small>${OPP[arenaChoice.opp].name}</small></div>`:""}`;$("ynuArenaMine").onclick=pickArenaJelly;$("ynuArenaOpp").onclick=pickOpponent;$("ynuArenaMove").onclick=pickMove;$("ynuArenaStart").onclick=startArenaFight;$("ynuArenaBoard").onclick=showArenaDashboard}
  async function pickArenaJelly(){const list=await placedV2();if(!list.length)return message("ไม่มีนักมวย","ต้องวางแมงกะพรุน V2 ในบ่อ 1 หรือบ่อ 2 ก่อนจึงจะขึ้นสังเวียนได้");$("modalContent").innerHTML=`<section class="feature-panel ynu-arena-choice-panel"><h2>เลือกแมงกะพรุนของเรา</h2><div class="ynu-arena-picker">${list.map((x,i)=>`<button class="${arenaChoice.jelly?.id===x.id?"selected":""}" data-arena-jelly="${i}"><img src="${x.type.image}"><b>${esc(x.customName||x.type.name)}</b><small>บ่อ ${x.pond}</small></button>`).join("")}</div></section>`;document.querySelectorAll("[data-arena-jelly]").forEach(b=>b.onclick=()=>{arenaChoice.jelly=list[Number(b.dataset.arenaJelly)];closeModal();drawArena()});openModal()}
  function pickOpponent(){$("modalContent").innerHTML=`<section class="feature-panel ynu-arena-choice-panel"><h2>เลือกคู่แข่ง</h2><div class="ynu-arena-picker">${OPP.map((x,i)=>`<button class="${arenaChoice.opp===i?"selected":""}" data-arena-opp="${i}"><img src="${x.image}"><b>${x.name}</b></button>`).join("")}</div></section>`;document.querySelectorAll("[data-arena-opp]").forEach(b=>b.onclick=()=>{arenaChoice.opp=Number(b.dataset.arenaOpp);closeModal();drawArena()});openModal()}
  function pickMove(){$("modalContent").innerHTML=`<section class="feature-panel ynu-arena-choice-panel ynu-arena-move-panel"><h2>เลือกท่าต่อสู้</h2><div class="ynu-move-picker">${MOVES.map(x=>`<button class="${arenaChoice.move===x.id?"selected":""}" data-arena-move="${x.id}"><img src="${x.image}"><small>${x.name}</small></button>`).join("")}</div></section>`;document.querySelectorAll("[data-arena-move]").forEach(b=>b.onclick=()=>{arenaChoice.move=Number(b.dataset.arenaMove);closeModal();drawArena()});openModal()}
  async function startArenaFight(){return false}
