  const M200_CROP_KEYS=["madCarrot","angryCorn","clockworkMushroom","staringMelon"];
  const M200_MENU_IDS=["rabbitMenu1","rabbitMenu2","rabbitMenu3","rabbitMenu4","rabbitMenu5","rabbitMenu6"];
  const M200_NEW_RIVER_KEYS=[];
