  function spriteAsset(color,stage=1,kind="idle"){
    const suffix=kind==="idle"?"idle":`${kind}-walk`;
    if(color==="black")return `alpaca-black-stage-${stage}-${suffix}.png?v=${VERSION}`;
    if(color==="pink")return `alpaca-pink-stage-${stage}-${suffix}.png?v=${VERSION}`;
    if(color==="green")return `alpaca-green-stage-${stage}-${suffix}.png?v=${VERSION}`;
    if(color==="brown")return `alpaca-brown-stage-${stage}-${suffix}.png?v=${VERSION}`;
    if(color==="goldenHoney")return `alpaca-golden-honey-stage-${stage}-${suffix}.png?v=${VERSION}`;
    if(color==="thaiTea")return `alpaca-thai-tea-stage-${stage}-${suffix}.png?v=${VERSION}`;
    if(color==="prince"){const m=kind==="idle"?"idle":`${kind}_walk`;return `alpaca-prince-stage${stage}_${m}.png?v=R31`}
    if(color==="princess"){const m=kind==="idle"?"idle":`${kind}_walk`;return `alpaca-princess-stage${stage}_${m}.png?v=R31`}
    return `alpaca-stage-${stage}-${suffix}.png?v=${VERSION}`;
  }
  function idleRatio(color,stage=1){return IDLE_RATIO[color]?.[stage]||160/225}
  function spritePreview(color,stage=1,extra=""){
    const ratio=idleRatio(color,stage),useColorIcon=(color==="thaiTea"||color==="goldenHoney")&&/(manage|warehouse|craft|reward|list)/i.test(String(extra||""));
    if(useColorIcon){
      const icon=COLOR_META[color]?.icon||"";
      const fallback=spriteAsset(color,1,"idle");
      return `<img class="alpaca-card-icon ${extra}" src="${icon}?v=264" alt="${safeHtml(colorName(color))}" loading="eager" decoding="async" onerror="if(!this.dataset.fallback){this.dataset.fallback='1';this.src='${fallback}';this.classList.add('alpaca-card-icon-fallback')}">`;
    }
    return `<span class="alpaca-sprite-preview alpaca-color-${safeHtml(color)} ${extra}" data-alpaca-color="${safeHtml(color)}" style="--alpaca-preview-ratio:${ratio};aspect-ratio:${ratio};background-image:url('${spriteAsset(color,stage,"idle")}')"></span>`
  }

