  function renderPenEvents(root){const layer=$("alpacaPenEventLayer");if(!layer)return;layer.innerHTML="";buildPenEvents(root,currentPen).forEach(ev=>{const b=document.createElement("button");b.type="button";b.className=`alpaca-pen-event ${ev.type}`;b.style.left=`${ev.point[0]}%`;b.style.top=`${ev.point[1]}%`;b.innerHTML=`<img src="${ev.image}" alt="${ev.label}">`;if(ev.type==="hole")b.onclick=()=>claimPenHole(ev);else if(ev.type==="mushroom")b.onclick=()=>confirmMagicMushroom(ev,"pen");layer.appendChild(b)})}

  function ingredientCount(s,key){const meta=INGREDIENT_META[key];if(!meta)return 0;if(meta.bucket==="specials")return Number(s.specials?.[key])||0;if(meta.bucket==="animalProducts")return Number(s.animalProducts?.[key])||0;if(meta.bucket==="alpacaOther")return Number(s.alpaca?.inventory?.other?.magicMushroom)||0;if(meta.bucket==="bag")return Number(s.bag?.[key])||0;if(meta.bucket==="coconutRiver")return Number(s.coconutRiverItems?.[key])||0;return 0}
  function takeIngredient(s,key,qty){const meta=INGREDIENT_META[key];if(meta.bucket==="specials")s.specials[key]=(Number(s.specials?.[key])||0)-qty;else if(meta.bucket==="animalProducts")s.animalProducts[key]=(Number(s.animalProducts?.[key])||0)-qty;else if(meta.bucket==="alpacaOther")s.alpaca.inventory.other.magicMushroom=(Number(s.alpaca.inventory.other.magicMushroom)||0)-qty;else if(meta.bucket==="bag")s.bag[key]=(Number(s.bag?.[key])||0)-qty;else if(meta.bucket==="coconutRiver")s.coconutRiverItems[key]=(Number(s.coconutRiverItems?.[key])||0)-qty}

  async function mutateOwn(mutator,{updateProfile=false}={}){
    if(!currentMemberKey||!ownState)throw new Error("ยังไม่พบข้อมูลผู้เล่น");
    const next=normalizeState(cloneData(ownState),currentMember);topupAdminAlpacaInventory(next);const result=mutator(next);topupAdminAlpacaInventory(next);applyOwn(next);saveLocalOnly(next);queueCloudSave();return{state:next,result};
  }

  /* R32.6: durable economy mutation for SELL actions.
     Read authoritative save -> remove sold instance/stock -> add merit -> commit once.
     Success UI must only happen after this promise resolves. */
  async function mutateOwnSale(mutator){
    if(!currentMemberKey||!ownState)throw new Error("ยังไม่พบข้อมูลผู้เล่น");
    try{await settlePendingCloudSave?.()}catch(_){}
    const {db,fs}=await getFirebaseContext();
    const saveRef=fs.doc(db,"saves",currentMemberKey),profileRef=fs.doc(db,"publicProfiles",currentMemberKey);
    let next,result;
    await fs.runTransaction(db,async tx=>{
      const snap=await tx.get(saveRef);
      if(!snap.exists())throw new Error("ไม่พบเซฟสมาชิก");
      const st=normalizeState(snap.data(),currentMember);
      ensureAlpacaState(st);
      result=mutator(st);
      next=cloneData(st);
      tx.set(saveRef,{...cloneData(st),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});
      tx.set(profileRef,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),merit:Number(st.merit)||0,initialized:true,updatedAt:fs.serverTimestamp()},{merge:true});
    });
    ownState=normalizeState(next,currentMember);state=ownState;saveLocalOnly(ownState);updateMeritUI();
    return{state:ownState,result};
  }

  /* S2 FIX2: low-risk pen actions update locally first, then use the existing queued cloud save.
     Cross-player / economy-sensitive actions still keep their original Firestore transactions. */
  function mutateOwnFast(mutator){
    if(!currentMemberKey||!ownState)throw new Error("ยังไม่พบข้อมูลผู้เล่น");
    const next=normalizeState(cloneData(ownState),currentMember);
    topupAdminAlpacaInventory(next);
    const result=mutator(next);
    topupAdminAlpacaInventory(next);
    applyOwn(next);
    try{saveLocalOnly(next)}catch{}
    try{queueCloudSave()}catch{}
    return{state:next,result};
  }

  function panelHero(image,title,subtitle=""){
    return `<div class="alpaca-panel-hero">${image?`<img class="alpaca-hero-icon" src="${image}" alt="">`:""}<div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:""}</div></div>`;
  }
  function findAnimal(s,penNo,id){const root=s?.alpaca||ownAlpaca(),pen=penAt(root,penNo);if(!pen)return{};return{root,pen,animal:pen.alpacas.find(a=>a.id===id)}}
  function findOwnAnimal(penNo,id){return findAnimal(ownState||state,penNo,id)}
  function sexLabel(a){return a?.sex==="female"?"ตัวเมีย":"ตัวผู้"}
  function colorName(color){return COLOR_META[color]?.name||"สีขาว"}
  function woolStageCountdown(a,now=gameNow()){if(a.type!=="adult")return"";return a.woolStage>=4?"พร้อมตัดขน":`ระยะ ${a.woolStage} • อีก ${fmt(Math.max(0,a.woolStageEndsAt-now))}`}
  function breedingStatusText(a,now=gameNow()){
    if(a.type!=="adult")return"-";
    if(a.sex==="male")return a.breederCooldownUntil>now?`คูลดาวน์ ${fmt(a.breederCooldownUntil-now)}`:"พร้อมเป็นพ่อพันธุ์";
    if(a.breedingUntil>now)return`กำลังผสมพันธุ์ ${fmt(a.breedingUntil-now)}`;
    if(a.pregnantUntil>now)return`ตั้งครรภ์ • คลอดใน ${fmt(a.pregnantUntil-now)}`;
    if(a.breedReadyAt>0&&a.breedReadyAt<=now)return"พร้อมผสมพันธุ์";
    if(a.breedReadyAt>now)return`พร้อมผสมใน ${fmt(a.breedReadyAt-now)}`;
    return a.everSheared?"กำลังรอรอบผสมพันธุ์":"ต้องตัดขนครั้งแรกก่อน";
  }

