      try{await settlePendingCloudSave();const {db,fs}=await getFirebaseContext(),pRef=fs.doc(db,"shared","jellyfishPond2"),sRef=fs.doc(db,"saves",currentMemberKey),prof=fs.doc(db,"publicProfiles",currentMemberKey);let next,pond;await fs.runTransaction(db,async tx=>{const [ps,ss]=await Promise.all([tx.get(pRef),tx.get(sRef)]);if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");const p=normJ2(ps.data()),x=p.slots[i],st=normalizeState(ss.data(),currentMember);if(!x||x.ownerKey!==currentMemberKey)throw new Error("ไม่พบแมงกะพรุนของคุณ");p.slots[i]=null;st.merit=(Number(st.merit)||0)+10;next=st;pond=p;tx.set(sRef,{...cloneData(st),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(pRef,{slots:p.slots,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(prof,{memberKey:currentMemberKey,displayName:currentProfileDisplayName(),merit:st.merit,initialized:true,updatedAt:fs.serverTimestamp()},{merge:true})});if(typeof Y26_applyOwnState==="function")Y26_applyOwnState(next);else{ownState=normalizeState(next,currentMember);state=ownState}jelly2Cache=pond;updateMeritUI();closeModal();drawJ2();showWeatherToast("🪼 ขายแมงกะพรุนแล้ว • +10 กุศล")}catch(e){message("ขายแมงกะพรุนไม่ได้",e.message||"กรุณาลองใหม่")}
