    const rows=available.map(([k,b])=>`<button data-s2-home-bait="${k}" ${(Number(s.fishingBaits?.[k])||0)<1?"disabled":""}><img src="${b.image}" alt=""><span><b>${b.name}</b><small>มี ×${Number(s.fishingBaits?.[k])||0} • ${Math.round((b.durationMs||60000)/60000)} นาที • ได้ ${FISH_QTY[k][0]}–${FISH_QTY[k][1]} ชิ้น</small></span></button>`).join("");
    $("modalContent").innerHTML=`<section class="feature-panel s2-home-fishing"><h2>🎣 แท่นตกปลาฟาร์ม2</h2><p class="feature-subtitle">เลือกเบ็ดที่มีอยู่ • ไม่ใช้เบ็ดเทพารักษ์ • ระบบนี้แยกจากบ่อตกปลาของยัยหนู</p><div class="s2-home-bait-grid">${rows}</div></section>`;document.querySelectorAll("[data-s2-home-bait]").forEach(b=>b.onclick=()=>startHomeFishing(b.dataset.s2HomeBait));openModal();
