            const p=Math.max(0,Math.min(1,(clock-h.motionStartedAt)/Math.max(1,h.duration)));const ease=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;rx=h.fromX+(h.tx-h.fromX)*ease;ry=h.fromY+(h.ty-h.fromY)*ease;
