  const scoreFlower=(key,count,receipt)=>score('home',(FLOWER_SCORE[key]||0)*Math.max(1,Number(count)||1),receipt);
  const scoreWine=(key,receipt)=>score('home',WINE_SCORE[key]||0,receipt);
