/* =====================================================================
   S2 R32.10 — SOLD INSTANCE TOMBSTONES + LOCAL MIRROR
   Prevent sold dog/cat/alpaca instances from being resurrected by stale
   save listeners or delayed full-state writes after a successful sale.
   ===================================================================== */
(function YN_R32_10_SALE_TOMBSTONES(){
  "use strict";
  const BUILD="S2-R32.10-SALE-TOMBSTONES-HOTEL-CONTINUITY";
  const storageKey=()=>`yn:r3210:sold:${String(currentMemberKey||currentMember||"guest")}`;
  function readLocal(){try{return JSON.parse(localStorage.getItem(storageKey())||"{}")||{}}catch(_){return{}}}
  function writeLocal(v){try{localStorage.setItem(storageKey(),JSON.stringify(v||{}))}catch(_){}}
  function mergeTombstones(s){
    if(!s)return s;
    const local=readLocal(),cloud=s.saleTombstones&&typeof s.saleTombstones==="object"?s.saleTombstones:{};
    const merged={dogs:{},cats:{},alpacas:{}};
    for(const k of Object.keys(merged))Object.assign(merged[k],cloud[k]||{},local[k]||{});
    s.saleTombstones=merged;writeLocal(merged);
    const sold=(k,id)=>Boolean(id&&merged[k]?.[String(id)]);
    if(Array.isArray(s.dogs))s.dogs=s.dogs.filter(x=>!sold("dogs",x?.id));
    if(Array.isArray(s.cats))s.cats=s.cats.filter(x=>!sold("cats",x?.id));
    if(s.alpaca){
      if(Array.isArray(s.alpaca.vault))s.alpaca.vault=s.alpaca.vault.filter(x=>!sold("alpacas",x?.id));
      if(Array.isArray(s.alpaca.pens))for(const p of s.alpaca.pens||[])if(Array.isArray(p?.alpacas))p.alpacas=p.alpacas.filter(x=>!sold("alpacas",x?.id));
    }
    return s;
  }
  if(typeof normalizeState==="function"){
    const base=normalizeState;
    normalizeState=function(raw,player){return mergeTombstones(base(raw,player))};
  }
  function syncCurrent(){try{if(ownState)mergeTombstones(ownState);if(state&&!visitContext)mergeTombstones(state)}catch(_){}}
  window.addEventListener("focus",syncCurrent,{passive:true});
  document.addEventListener("visibilitychange",()=>{if(!document.hidden)syncCurrent()},{passive:true});
  setInterval(syncCurrent,5000);
  globalThis.YN_R3210={BUILD,mergeTombstones,readLocal};
  globalThis.YAINOO_BUILD=BUILD;
  console.info(BUILD,"loaded");
})();


