    try{ensurePlotPhaseStandalone?.(local)}catch(_){}
    if(!local?.crop||(local.phase!=="worm"&&!local.worm))return message("กำจัดหนอนไม่ได้","แปลงนี้ไม่มีหนอนค่ะ");
