  async function claimDisc(kind,scope){if(!currentMemberKey||discBusy)return;discBusy=true;try{const {db,fs}=await getFirebaseContext(),sref=fs.doc(db,"saves",currentMemberKey),dref=fs.doc(db,"animalDiscState",currentMemberKey);let qty=0,newQty=0,nextD=null;await fs.runTransaction(db,async tx=>{const [ss,ds]=await Promise.all([tx.get(sref),tx.get(dref)]);if(!ss.exists()||!ds.exists())throw new Error("ไม่พบข้อมูลดรอป");const save=normalizeState(ss.data(),currentMember),d=normDisc(ds.data()),arr=kind==="royal"?d.royalByPen[String(scope)]:d.hamByFarm[String(scope)];qty=arr.reduce((n,x)=>n+(Number(x?.qty)||1),0);if(!qty)throw new Error("ไม่มีของดรอปค้างอยู่");const key=kind==="royal"?"therapyDiscPink":"therapyDiscRock";save.specials=save.specials||{};newQty=isAdminNow()?9999:(Number(save.specials[key])||0)+qty;arr.splice(0,arr.length);tx.update(sref,{[`specials.${key}`]:newQty,updatedAt:fs.serverTimestamp()});tx.set(dref,{...d,memberKey:currentMemberKey,updatedAt:fs.serverTimestamp()},{merge:false});nextD=d});discCache=nextD;const s=liveOwner();if(s){s.specials=s.specials||{};s.specials[kind==="royal"?"therapyDiscPink":"therapyDiscRock"]=newQty;try{saveLocalOnly?.(s)}catch(_){ }}renderDisc();message?.("💿 รับเรียบร้อย",`${kind==="royal"?"แผ่นเพลงบำบัดหัวใจหวาน":"แผ่นเพลงบำบัดพลังร็อก"} ×${qty}`)}catch(e){message?.("รับดรอปไม่ได้",e?.message||"กรุณาลองใหม่ค่ะ")}finally{discBusy=false}}
