  function fmt(ms){ms=Math.max(0,Math.floor(Number(ms)||0));const m=Math.floor(ms/60000),sec=Math.floor((ms%60000)/1000);return `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`}

