  if(visitContext||$("alpacaPenScreen")?.classList.contains("hidden")){l.replaceChildren();l.classList.add("hidden");return}l.classList.remove("hidden");const s=ensureAlpaca(ownState||state),p=currentPen(),arr=s?.alpaca?.r3451RoyalDrops?.[`pen${p}`]||[];
