  async function durablePlant(index,key,button){index=Math.floor(Number(index));if(visitContext||plantBusy.has(index)||!cloudReady||!currentMemberKey)return false;const crop=CROPS?.[key];if(!crop)return false;plantBusy.add(index);if(button){button.disabled=true;button.dataset.r3465Busy="1"}const actionId=`plant-${currentMemberKey}-${index}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,t=now();try{await settlePendingCloudSave?.();const {db,fs}=await getFirebaseContext(),saveRef=fs.doc(db,"saves",currentMemberKey),gardenRef=fs.doc(db,"gardens",currentMemberKey);let next=null;await YN_RETRY_TX(()=>fs.runTransaction(db,async tx=>{const ss=await tx.get(saveRef);if(!ss.exists())throw new Error("ไม่พบเซฟสมาชิก");const st=normalizeState(ss.data(),currentMember);assertCurrentCloudSession?.(ss.data(),currentMember);const p=st.plots?.[index];if(p?.crop){if(String(p.r3465PlantAction||"")===actionId){next=st;return}throw new Error("แปลงนี้ถูกปลูกไปแล้ว")};const cost=Number(crop.seedCostMerit)||0;if(cost&&!admin()&&Number(st.merit)<cost)throw new Error(`${crop.name} ใช้ ${cost} กุศล / 1 เมล็ด`);if(cost&&!admin())st.merit-=cost;try{incrementMissionOn?.(st,"dailyPlantCrops",1)}catch(_){};st.angelPlantCounter=(Number(st.angelPlantCounter)||0)+1;const angel=st.angelPlantCounter>=30;if(angel)st.angelPlantCounter=0;st.plots[index]={crop:key,phase:"growing1",phaseEndsAt:t+Number(crop.waterMs||0),plantedAt:t,wateredAt:0,worm:false,angel,r3465PlantAction:actionId};if(admin())try{ensureAdminStock?.(st)}catch(_){};st.clientSaveRevision=(Number(st.clientSaveRevision)||0)+1;next=clone(st);tx.set(saveRef,{...clone(st),activeSessionId:cloudSessionId,updatedAt:fs.serverTimestamp()},{merge:false});tx.set(gardenRef,{memberKey:currentMemberKey,displayName:typeof currentProfileDisplayName==="function"?currentProfileDisplayName():currentMember,plots:clone(st.plots),updatedAt:fs.serverTimestamp()},{merge:true})}));applyServerState(next);try{lastGardenHash=plotHash(ownState.plots)}catch(_){};closeModal?.();draw?.();showWeatherToast?.(`🌱 ปลูก ${crop.name} แปลง #${index+1} แล้ว • บันทึกเรียบร้อย`);return true}catch(e){message("ปลูกไม่ได้",e?.message||"กรุณาลองใหม่ค่ะ");return false}finally{plantBusy.delete(index);if(button&&button.isConnected){button.disabled=false;delete button.dataset.r3465Busy}}}
  try{Y26_plantCrop=durablePlant;globalThis.Y26_plantCrop=durablePlant}catch(_){}

  /* Jellyfish items/boxes stay. Pond routes and placement are retired. */
  try{$("shortcutJellyfishBtn")?.remove();$("riverHotspot")?.remove()}catch(_){}
