  if(openSceneBase)openScene=function(name){if(["jellyfish","jellyfish2","jellyfishArena"].includes(String(name))){try{stopJellyPondSubscription?.()}catch(_){};try{returnToFarm?.()}catch(_){};showWeatherToast?.("🪼 แมงกะพรุนยังอยู่ในกระเป๋า • ระบบบ่อถูกนำออกแล้ว");return}return openSceneBase.apply(this,arguments)};
  try{showJellyPlacement=function(){message("🪼 ระบบบ่อถูกนำออกแล้ว","แมงกะพรุนยังเก็บในกระเป๋าได้ตามปกติ และจะใช้เป็นวัตถุดิบเมนูในอนาคตค่ะ")};placeJellyfish=async function(){return message("🪼 วางไม่ได้","ระบบวางแมงกะพรุนลงบ่อถูกนำออกแล้วค่ะ")}}catch(_){}

  /* Persistent gift inbox: pending docs in /gifts are authoritative, not the latest
     mailbox toast. This recovers gifts even if an older mailbox notification vanished. */
  async function pendingGiftDocs(){if(!cloudReady||!currentMemberKey)return[];const {db,fs}=await getFirebaseContext(),ref=fs.collection(db,"gifts");let rows=[];try{const q=fs.query(ref,fs.where("toKey","==",currentMemberKey),fs.limit(200)),sn=await fs.getDocs(q);sn.forEach(d=>{const x=d.data()||{};if(x.status==="pending")rows.push({id:d.id,...x})})}catch(e){console.warn(BUILD,"pending gifts",e)}return rows.sort((a,b)=>{const av=typeof timestampMillis==="function"?timestampMillis(a.createdAt):0,bv=typeof timestampMillis==="function"?timestampMillis(b.createdAt):0;return bv-av})}
  const notifyBase=typeof showNotifications==="function"?showNotifications:null;
  if(notifyBase)showNotifications=async function(tab="friend"){
    if(tab!=="yainoo")return notifyBase.apply(this,arguments);
    if(!cloudReady)return message("การแจ้งเตือนยังไม่พร้อม","กรุณาเชื่อม Firebase ก่อน");
    try{const [mail,broadcasts,direct]=await Promise.all([fetchMailboxItems(),fetchBroadcasts(),pendingGiftDocs()]),yMail=mail.filter(x=>x.source==="yainoo"),aidaPending=direct.filter(x=>String(x.fromKey||"").toLowerCase()==="aida"||String(x.fromName||"").toLowerCase()==="aida"),mailGiftIds=new Set(yMail.map(x=>String(x.giftId||x.id||"")));const directCards=aidaPending.map(g=>{const summary=Array.isArray(g.items)?g.items.map(x=>`${x.name||x.key} ×${iv(x.qty)||1}`).join(" • "):`${g.itemName||g.itemKey||"ของขวัญ"} ×${iv(g.qty)||1}`;return `<div class="notification-card unread r3465-pending-gift"><b>🎁 ของขวัญจากยัยหนู</b><span>${esc(summary)}</span><small>${typeof bangkokTimeText==="function"?bangkokTimeText(g.createdAt):""} น.</small><div class="notification-actions"><button type="button" data-r3465-gift="${g.id}" data-act="accept">รับของขวัญ</button><button type="button" data-r3465-gift="${g.id}" data-act="discard">ทิ้ง</button></div></div>`}).join("");const otherMail=yMail.filter(x=>!mailGiftIds.has(String(x.giftId||""))||!aidaPending.some(g=>g.id===String(x.giftId||x.id))).map(x=>`<div class="notification-card ${x.read?"":"unread"}"><b>${esc(x.title||"แจ้งเตือนจากยัยหนู")}</b>${x.text?`<span>${esc(x.text)}</span>`:""}<small>${typeof bangkokTimeText==="function"?bangkokTimeText(x.createdAt):""} น.</small></div>`).join("");const claims=await Promise.all(broadcasts.map(b=>b.type==="gift"?fetchBroadcastClaimCached(b.id):Promise.resolve(null)));const bc=broadcasts.map((b,idx)=>{const claim=claims[idx],sum=Array.isArray(b.items)?b.items.map(x=>`${x.name||x.key} ×${iv(x.qty)||1}`).join(" • "):(b.itemName?`${b.itemName} ×${iv(b.qty)||1}`:"");return `<div class="notification-card"><b>${esc(b.title||"ข้อความจากยัยหนู")}</b>${b.body?`<span>${esc(b.body)}</span>`:""}${sum?`<span>🎁 ${esc(sum)}</span>`:""}${b.type==="gift"?`<div class="notification-actions">${claim?`<button disabled>${claim.status==="accepted"?"รับแล้ว":"ทิ้งแล้ว"}</button>`:`<button data-r3465-broadcast="${b.id}" data-act="accept">รับของขวัญ</button><button data-r3465-broadcast="${b.id}" data-act="discard">ทิ้ง</button>`}</div>`:""}</div>`}).join("");const allIds=aidaPending.map(x=>x.id);$("modalContent").innerHTML=`<section class="feature-panel notification-panel"><h2>🔔 การแจ้งเตือน</h2><div class="notification-tabs"><button data-notification-tab="friend">👥 จากเพื่อน</button><button data-notification-tab="yainoo" class="active">👑 จากยัยหนู</button></div>${allIds.length>1?`<button id="r3465ClaimAllAida" class="primary-spooky-action">🎁 รับของขวัญที่ค้างทั้งหมด (${allIds.length})</button>`:""}<div class="notification-list">${directCards}${otherMail}${bc||""}</div></section>`;document.querySelectorAll('[data-notification-tab]').forEach(b=>b.onclick=()=>showNotifications(b.dataset.notificationTab));document.querySelectorAll('[data-r3465-gift]').forEach(b=>b.onclick=()=>claimFriendGift(b.dataset.r3465Gift,b.dataset.act==="accept","yainoo"));document.querySelectorAll('[data-r3465-broadcast]').forEach(b=>b.onclick=()=>claimBroadcastGift(b.dataset.r3465Broadcast,b.dataset.act==="accept"));if($("r3465ClaimAllAida"))$("r3465ClaimAllAida").onclick=async()=>{const b=$("r3465ClaimAllAida");b.disabled=true;b.textContent="กำลังรับทั้งหมด…";for(const id of allIds)await claimFriendGift(id,true,"yainoo");showNotifications("yainoo")};openModal();try{await markMailboxRead(yMail)}catch(_){};try{refreshNotificationBadge?.(true)}catch(_){}
    }catch(e){message("เปิดการแจ้งเตือนไม่ได้",e?.message||"กรุณาลองใหม่ค่ะ")}
  };

  /* Cached-first merit Rank: render last good snapshot immediately, then refresh. */
  const rankKey=()=>`yn:r3465:rank:${currentMemberKey||"guest"}`;
  function renderRank(map){const names=Object.keys(typeof MEMBERS!=="undefined"?MEMBERS:{}),aidaName=names.find(n=>String(n).toLowerCase()==="aida")||"Aida",rows=names.filter(n=>String(n).toLowerCase()!=="aida").map(name=>{const key=memberKeyFromName(name),p=map[key]||{};return{name,key,merit:Number(p.merit??300)||0,initialized:p.initialized!==false,level:Math.max(0,Math.min(3,Number(p.houseLevel)||0))}}).sort((a,b)=>b.merit-a.merit||a.name.localeCompare(b.name));const ak=memberKeyFromName(aidaName),ap=map[ak]||{},aa={name:aidaName,key:ak,merit:Number(ap.merit??0)||0,level:Math.max(0,Math.min(3,Number(ap.houseLevel)||0))};const act=r=>r.name===currentMember?'<span class="friend-self">คุณ</span>':`<span class="friend-actions"><button data-r3465-visit="${esc(r.key)}" data-name="${esc(r.name)}">เยี่ยมสวน</button><button data-r3465-gift-friend="${esc(r.key)}" data-name="${esc(r.name)}">ส่งของ</button></span>`,row=(r,n,adm=false)=>`<div class="friend-row friend-rank-row ${adm?"r3411-rank-admin":n<=3?`r3411-rank-top-${n}`:""}"><span class="friend-rank">${adm?"ADMIN":`#${n}`}</span><span class="friend-avatar">${adm?"👑":"👻"}</span><span class="friend-info"><b>${esc(r.name)}</b><small>${adm?"👑 ผู้ดูแลระบบ • ไม่นับอันดับ":`🙏 ${Number(r.merit).toLocaleString("th-TH")} กุศล`}</small><small>🏠 Lv.${r.level}</small></span>${act(r)}</div>`;$("modalContent").innerHTML=`<section class="feature-panel friends-panel r3411-rank-panel"><h2>👥 เพื่อน & Rank กุศล</h2><div class="friend-list friend-rank-list">${row(aa,0,true)}${rows.map((r,n)=>row(r,n+1)).join("")}</div></section>`;openModal();document.querySelectorAll('[data-r3465-visit]').forEach(b=>b.onclick=()=>visitFriend(b.dataset.r3465Visit,b.dataset.name));document.querySelectorAll('[data-r3465-gift-friend]').forEach(b=>b.onclick=()=>showGiftComposer?.(b.dataset.r3465GiftFriend,b.dataset.name))}
  showFriends=async function(){if(typeof guardResting==="function"&&guardResting())return;let cached={};try{cached=JSON.parse(localStorage.getItem(rankKey())||"{}")||{}}catch(_){};renderRank(cached);if(!cloudReady)return;try{const {db,fs}=await getFirebaseContext(),sn=await fs.getDocs(fs.collection(db,"publicProfiles")),fresh={};sn.forEach(d=>fresh[d.id]=d.data()||{});try{localStorage.setItem(rankKey(),JSON.stringify(fresh))}catch(_){};renderRank(fresh)}catch(e){console.warn(BUILD,"rank refresh",e)}};

  globalThis.YAINOO_BUILD=BUILD;console.info(BUILD,"loaded");
